-- Name: user_restaurants_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_restaurants_admin() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
