gres\\"","CREATE TYPE \\"public\\".\\"capacity_override_type\\" AS ENUM (\n    'holiday',\n    'event',\n    'manual',\n    'emergency'\n)","ALTER TYPE \\"public\\".\\"capacity_override_type\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"loyalty_tier\\" AS ENUM (\n    'bronze',\n    'silver',\n    'gold',\n    'platinum'\n)","ALTER TYPE \\"public\\".\\"loyalty_tier\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"seating_preference_type\\" AS ENUM (\n    'any',\n    'indoor',\n    'outdoor',\n    'bar',\n    'window',\n    'quiet',\n    'booth'\n)","ALTER TYPE \\"public\\".\\"seating_preference_type\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"table_category\\" AS ENUM (\n    'bar',\n    'dining',\n    'lounge',\n    'patio',\n    'private'\n)","ALTER TYPE \\"public\\".\\"table_category\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"table_mobility\\" AS ENUM (\n    'movable',\n    'fixed'\n)","ALTER TYPE \\"public\\".\\"table_mobility\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"table_seating_type\\" AS ENUM (\n    'standard',\n    'sofa',\n    'booth',\n    'high_top'\n)","ALTER TYPE \\"public\\".\\"table_seating_type\\" OWNER TO \\"postgres\\"","CREATE TYPE \\"public\\".\\"table_status\\" AS ENUM (\n    'available',\n    'reserved',\n    'occupied',\n    'out_of_service'\n)","ALTER TYPE \\"public\\".\\"table_status\\" OWNER TO \\"postgres\\"","COMMENT ON TYPE \\"public\\".\\"table_status\\" IS 'Status of a restaurant table: available, reserved (booked), occupied (guests seated), out_of_service (maintenance)'","CREATE OR REPLACE FUNCTION \\"public\\".\\"allocations_overlap\\"(\\"a\\" \\"tstzrange\\", \\"b\\" \\"tstzrange\\") RETURNS boolean\n    LANGUAGE \\"sql\\" IMMUTABLE\n    AS $$\n  SELECT COALESCE(a && b, false);\n$$","ALTER FUNCTION \\"public\\".\\"allocations_overlap\\"(\\"a\\" \\"tstzrange\\", \\"b\\" \\"tstzrange\\") OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"allocations_overlap\\"(\\"a\\" \\"tstzrange\\", \\"b\\" \\"tstzrange\\") IS 'Returns true when two timestamptz ranges overlap (half-open [start,end) semantics).'","CREATE OR REPLACE FUNCTION \\"public\\".\\"allowed_capacities_set_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  NEW.updated_at := timezone('utc', now());\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"allowed_capacities_set_updated_at\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"apply_booking_state_transition\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_status\\" \\"public\\".\\"booking_status\\", \\"p_checked_in_at\\" timestamp with time zone, \\"p_checked_out_at\\" timestamp with time zone, \\"p_updated_at\\" timestamp with time zone, \\"p_history_from\\" \\"public\\".\\"booking_status\\", \\"p_history_to\\" \\"public\\".\\"booking_status\\", \\"p_history_changed_by\\" \\"uuid\\", \\"p_history_changed_at\\" timestamp with time zone, \\"p_history_reason\\" \\"text\\", \\"p_history_metadata\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\") RETURNS TABLE(\\"status\\" \\"public\\".\\"booking_status\\", \\"checked_in_at\\" timestamp with time zone, \\"checked_out_at\\" timestamp with time zone, \\"updated_at\\" timestamp with time zone)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\nDECLARE\n    v_updated public.bookings%ROWTYPE;\nBEGIN\n    UPDATE public.bookings\n    SET\n        status = p_status,\n        checked_in_at = p_checked_in_at,\n        checked_out_at = p_checked_out_at,\n        updated_at = p_updated_at\n    WHERE id = p_booking_id\n    RETURNING * INTO v_updated;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Booking % not found', p_booking_id;\n    END IF;\n\n    INSERT INTO public.booking_state_history (\n        booking_id,\n        from_status,\n        to_status,\n        changed_by,\n        changed_at,\n        reason,\n        metadata\n    )\n    VALUES (\n        p_booking_id,\n        p_history_from,\n        p_history_to,\n        p_history_changed_by,\n        p_history_changed_at,\n        p_history_reason,\n        COALESCE(p_history_metadata, '{}'::jsonb)\n    );\n\n    RETURN QUERY\n    SELECT\n        v_updated.status,\n        v_updated.checked_in_at,\n        v_updated.checked_out_at,\n        v_updated.updated_at;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"apply_booking_state_transition\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_status\\" \\"public\\".\\"booking_status\\", \\"p_checked_in_at\\" timestamp with time zone, \\"p_checked_out_at\\" timestamp with time zone, \\"p_updated_at\\" timestamp with time zone, \\"p_history_from\\" \\"public\\".\\"booking_status\\", \\"p_history_to\\" \\"public\\".\\"booking_status\\", \\"p_history_changed_by\\" \\"uuid\\", \\"p_history_changed_at\\" timestamp with time zone, \\"p_history_reason\\" \\"text\\", \\"p_history_metadata\\" \\"jsonb\\") OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"are_tables_connected\\"(\\"table_ids\\" \\"uuid\\"[]) RETURNS boolean\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE\n  unique_tables uuid[];\n  start_table uuid;\n  total_count integer;\n  connected_count integer;\nBEGIN\n  SELECT array_agg(DISTINCT id)\n  INTO unique_tables\n  FROM unnest(table_ids) AS id\n  WHERE id IS NOT NULL;\n\n  total_count := array_length(unique_tables, 1);\n\n  IF total_count IS NULL OR total_count = 0 THEN\n    RETURN false;\n  END IF;\n\n  IF total_count = 1 THEN\n    RETURN true;\n  END IF;\n\n  start_table := unique_tables[1];\n\n  WITH RECURSIVE connected AS (\n    SELECT start_table AS table_id\n    UNION\n    SELECT adj.table_b\n    FROM connected\n    JOIN public.table_adjacencies adj\n      ON adj.table_a = connected.table_id\n    WHERE adj.table_b = ANY(unique_tables)\n  )\n  SELECT COUNT(DISTINCT table_id)\n  INTO connected_count\n  FROM connected;\n\n  RETURN connected_count = total_count;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"are_tables_connected\\"(\\"table_ids\\" \\"uuid\\"[]) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"assign_table_to_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\", \\"p_assigned_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\nDECLARE\n    v_assignment_id uuid;\n    v_restaurant_id uuid;\n    v_booking_date date;\n    v_start_time time;\n    v_slot_id uuid;\nBEGIN\n    -- Verify booking exists and get details\n    SELECT restaurant_id, booking_date, start_time \n    INTO v_restaurant_id, v_booking_date, v_start_time\n    FROM bookings\n    WHERE id = p_booking_id;\n    \n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Booking not found: %', p_booking_id;\n    END IF;\n    \n    -- Verify table exists and belongs to same restaurant\n    IF NOT EXISTS (\n        SELECT 1 FROM table_inventory\n        WHERE id = p_table_id AND restaurant_id = v_restaurant_id\n    ) THEN\n        RAISE EXCEPTION 'Table not found or belongs to different restaurant: %', p_table_id;\n    END IF;\n    \n    -- Get or create booking slot\n    SELECT id INTO v_slot_id\n    FROM booking_slots\n    WHERE restaurant_id = v_restaurant_id\n        AND slot_date = v_booking_date\n        AND slot_time = v_start_time;\n    \n    -- Create assignment\n    INSERT INTO booking_table_assignments (\n        booking_id,\n        table_id,\n        slot_id,\n        assigned_by,\n        notes\n    ) VALUES (\n        p_booking_id,\n        p_table_id,\n        v_slot_id,\n        p_assigned_by,\n        p_notes\n    )\n    ON CONFLICT (booking_id, table_id) DO UPDATE\n    SET assigned_by = EXCLUDED.assigned_by,\n        notes = EXCLUDED.notes,\n        assigned_at = now()\n    RETURNING id INTO v_assignment_id;\n    \n    -- Update table status to reserved\n    UPDATE table_inventory\n    SET status = 'reserved'::table_status\n    WHERE id = p_table_id;\n    \n    RETURN v_assignment_id;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"assign_table_to_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\", \\"p_assigned_by\\" \\"uuid\\", \\"p_notes\\" \\"text\\") OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"assign_table_to_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\", \\"p_assigned_by\\" \\"uuid\\", \\"p_notes\\" \\"text\\") IS 'Assign a table to a booking. Updates table status to reserved. Returns assignment ID.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"assign_tables_atomic\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_ids\\" \\"uuid\\"[], \\"p_window\\" \\"tstzrange\\", \\"p_assigned_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_idempotency_key\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS TABLE(\\"table_id\\" \\"uuid\\", \\"assignment_id\\" \\"uuid\\", \\"merge_group_id\\" \\"uuid\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\n    DECLARE\n      v_booking RECORD;\n      v_restaurant_id uuid;\n      v_target_tables uuid[];\n      v_requested_tables uuid[];\n      v_existing_tables uuid[];\n      v_table RECORD;\n      v_total_capacity integer := 0;\n      v_first_zone uuid := NULL;\n      v_merge_group_id uuid := NULL;\n      v_slot_id uuid := NULL;\n      v_now timestamptz := now();\n      v_window tstzrange := p_window;\n      v_assignment_id uuid;\n      v_loaded_count integer := 0;\n      v_table_id uuid;\n      v_lock_restaurant int4;\n      v_lock_date int4;\n    BEGIN\n      IF p_table_ids IS NULL OR array_length(p_table_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic requires at least one table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      SELECT array_agg(DISTINCT table_id)\n      INTO v_target_tables\n      FROM unnest(p_table_ids) AS t(table_id);\n\n      IF v_target_tables IS NULL OR array_length(v_target_tables, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic requires at least one valid table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      SELECT *\n      INTO v_booking\n      FROM public.bookings\n      WHERE id = p_booking_id\n      FOR UPDATE;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Booking % not found', p_booking_id\n          USING ERRCODE = 'P0002';\n      END IF;\n\n      v_restaurant_id := v_booking.restaurant_id;\n\n      v_lock_restaurant := hashtext(v_restaurant_id::text);\n      v_lock_date := COALESCE((v_booking.booking_date - DATE '2000-01-01')::int, 0);\n      PERFORM pg_advisory_xact_lock(v_lock_restaurant, v_lock_date);\n\n      IF v_window IS NULL THEN\n        v_window := tstzrange(v_booking.start_at, v_booking.end_at, '[)');\n      END IF;\n\n      IF v_window IS NULL OR lower(v_window) IS NULL OR upper(v_window) IS NULL OR lower(v_window) >= upper(v_window) THEN\n        RAISE EXCEPTION 'Invalid assignment window for booking %', p_booking_id\n          USING ERRCODE = '22000';\n      END IF;\n\n      IF p_idempotency_key IS NOT NULL THEN\n        SELECT array_agg(bta.table_id ORDER BY bta.table_id)\n        INTO v_existing_tables\n        FROM public.booking_table_assignments bta\n        WHERE bta.booking_id = p_booking_id\n          AND bta.idempotency_key = p_idempotency_key;\n\n        IF v_existing_tables IS NOT NULL THEN\n          SELECT array_agg(table_id ORDER BY table_id)\n          INTO v_requested_tables\n          FROM unnest(v_target_tables) AS t(table_id);\n\n          IF v_requested_tables IS NULL OR v_requested_tables <> v_existing_tables THEN\n            RAISE EXCEPTION 'assign_tables_atomic idempotency key mismatch'\n              USING ERRCODE = 'P0003',\n                    DETAIL = 'Idempotency key reuse detected with a different table set';\n          END IF;\n\n          RETURN QUERY\n            SELECT\n              bta.table_id,\n              bta.id AS assignment_id,\n              bta.merge_group_id\n            FROM public.booking_table_assignments bta\n            WHERE bta.booking_id = p_booking_id\n              AND bta.idempotency_key = p_idempotency_key;\n\n          RETURN;\n        END IF;\n      END IF;\n\n      FOR v_table IN\n        SELECT id, restaurant_id, zone_id, capacity\n        FROM public.table_inventory\n        WHERE id = ANY (v_target_tables)\n        ORDER BY id\n        FOR UPDATE\n      LOOP\n        IF v_table.restaurant_id <> v_restaurant_id THEN\n          RAISE EXCEPTION 'Table % belongs to a different restaurant', v_table.id;\n        END IF;\n\n        IF v_table.zone_id IS NULL THEN\n          RAISE EXCEPTION 'Table % is not assigned to a zone', v_table.id;\n        END IF;\n\n        IF v_first_zone IS NULL THEN\n          v_first_zone := v_table.zone_id;\n        ELSIF v_first_zone <> v_table.zone_id THEN\n          RAISE EXCEPTION 'All tables must belong to the same zone';\n        END IF;\n\n        v_total_capacity := v_total_capacity + COALESCE(v_table.capacity, 0);\n        v_loaded_count := v_loaded_count + 1;\n      END LOOP;\n\n      IF v_loaded_count <> array_length(v_target_tables, 1) THEN\n        RAISE EXCEPTION 'Unable to load all requested tables';\n      END IF;\n\n      IF array_length(v_target_tables, 1) > 1 THEN\n        INSERT INTO public.merge_groups (capacity, created_at)\n        VALUES (NULLIF(v_total_capacity, 0), v_now)\n        RETURNING id INTO v_merge_group_id;\n\n        INSERT INTO public.merge_group_members (merge_group_id, table_id)\n        SELECT v_merge_group_id, unnest(v_target_tables)\n        ON CONFLICT DO NOTHING;\n      END IF;\n\n      IF v_booking.booking_date IS NOT NULL AND v_booking.start_time IS NOT NULL THEN\n        SELECT id\n        INTO v_slot_id\n        FROM public.booking_slots\n        WHERE restaurant_id = v_restaurant_id\n          AND slot_date = v_booking.booking_date\n          AND slot_time = v_booking.start_time\n        LIMIT 1;\n\n        IF v_slot_id IS NULL THEN\n          SELECT public.get_or_create_booking_slot(v_restaurant_id, v_booking.booking_date, v_booking.start_time, 999)\n          INTO v_slot_id;\n        END IF;\n      END IF;\n\n      FOREACH v_table_id IN ARRAY v_target_tables LOOP\n        INSERT INTO public.booking_table_assignments (\n          booking_id,\n          table_id,\n          slot_id,\n          assigned_by,\n          idempotency_key,\n          merge_group_id\n        ) VALUES (\n          p_booking_id,\n          v_table_id,\n          v_slot_id,\n          p_assigned_by,\n          p_idempotency_key,\n          v_merge_group_id\n        )\n        ON CONFLICT (booking_id, table_id) DO UPDATE\n        SET assigned_by = EXCLUDED.assigned_by,\n            assigned_at = v_now,\n            idempotency_key = COALESCE(EXCLUDED.idempotency_key, public.booking_table_assignments.idempotency_key),\n            merge_group_id = COALESCE(EXCLUDED.merge_group_id, public.booking_table_assignments.merge_group_id)\n        RETURNING id INTO v_assignment_id;\n\n        BEGIN\n          INSERT INTO public.allocations (\n            booking_id,\n            restaurant_id,\n            resource_type,\n            resource_id,\n            \\"window\\",\n            created_by,\n            shadow,\n            created_at,\n            updated_at\n          ) VALUES (\n            p_booking_id,\n            v_restaurant_id,\n            'table',\n            v_table_id,\n            v_window,\n            p_assigned_by,\n            false,\n            v_now,\n            v_now\n          )\n          ON CONFLICT ON CONSTRAINT allocations_booking_resource_key DO UPDATE\n          SET \\"window\\" = EXCLUDED.\\"window\\",\n              created_by = EXCLUDED.created_by,\n              updated_at = v_now;\n        EXCEPTION\n          WHEN unique_violation OR exclusion_violation THEN\n            RAISE EXCEPTION 'allocations_no_overlap'\n              USING ERRCODE = 'P0001',\n                    DETAIL = format('Resource %s overlaps requested window for booking %s', v_table_id, p_booking_id);\n        END;\n\n        UPDATE public.table_inventory\n        SET status = 'reserved'::public.table_status\n        WHERE id = v_table_id;\n\n        table_id := v_table_id;\n        assignment_id := v_assignment_id;\n        merge_group_id := v_merge_group_id;\n        RETURN NEXT;\n      END LOOP;\n\n      IF v_merge_group_id IS NOT NULL THEN\n        BEGIN\n          INSERT INTO public.allocations (\n            booking_id,\n            restaurant_id,\n            resource_type,\n            resource_id,\n            \\"window\\",\n            created_by,\n            shadow,\n            created_at,\n            updated_at\n          ) VALUES (\n            p_booking_id,\n            v_restaurant_id,\n            'merge_group',\n            v_merge_group_id,\n            v_window,\n            p_assigned_by,\n            false,\n            v_now,\n            v_now\n          )\n          ON CONFLICT ON CONSTRAINT allocations_booking_resource_key DO UPDATE\n          SET \\"window\\" = EXCLUDED.\\"window\\",\n              created_by = EXCLUDED.created_by,\n              updated_at = v_now;\n        EXCEPTION\n          WHEN unique_violation OR exclusion_violation THEN\n            RAISE EXCEPTION 'allocations_no_overlap'\n              USING ERRCODE = 'P0001',\n                    DETAIL = format('Merge group %s overlaps requested window for booking %s', v_merge_group_id, p_booking_id);\n        END;\n      END IF;\n\n      RETURN;\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"assign_tables_atomic\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_ids\\" \\"uuid\\"[], \\"p_window\\" \\"tstzrange\\", \\"p_assigned_by\\" \\"uuid\\", \\"p_idempotency_key\\" \\"text\\") OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"booking_status_summary\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_end_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_status_filter\\" \\"public\\".\\"booking_status\\"[] DEFAULT NULL::\\"public\\".\\"booking_status\\"[]) RETURNS TABLE(\\"status\\" \\"public\\".\\"booking_status\\", \\"total\\" bigint)\n    LANGUAGE \\"sql\\"\n    AS $$\n    SELECT\n        b.status,\n        COUNT(*)::bigint AS total\n    FROM public.bookings b\n    WHERE b.restaurant_id = p_restaurant_id\n      AND (p_start_date IS NULL OR b.booking_date >= p_start_date)\n      AND (p_end_date IS NULL OR b.booking_date <= p_end_date)\n      AND (p_status_filter IS NULL OR b.status = ANY(p_status_filter))\n    GROUP BY b.status\n    ORDER BY b.status;\n$$","ALTER FUNCTION \\"public\\".\\"booking_status_summary\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\", \\"p_status_filter\\" \\"public\\".\\"booking_status\\"[]) OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"booking_status_summary\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\", \\"p_status_filter\\" \\"public\\".\\"booking_status\\"[]) IS 'Returns aggregated booking counts by status for a restaurant across an optional date range and status filter.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"capacity_metrics_hourly_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  NEW.updated_at := timezone('utc', now());\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"capacity_metrics_hourly_updated_at\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"create_booking_with_capacity_check\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_customer_id\\" \\"uuid\\", \\"p_booking_date\\" \\"date\\", \\"p_start_time\\" time without time zone, \\"p_end_time\\" time without time zone, \\"p_party_size\\" integer, \\"p_booking_type\\" \\"text\\", \\"p_customer_name\\" \\"text\\", \\"p_customer_email\\" \\"text\\", \\"p_customer_phone\\" \\"text\\", \\"p_seating_preference\\" \\"text\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_marketing_opt_in\\" boolean DEFAULT false, \\"p_idempotency_key\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_source\\" \\"text\\" DEFAULT 'api'::\\"text\\", \\"p_auth_user_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_client_request_id\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_details\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\", \\"p_loyalty_points_awarded\\" integer DEFAULT 0) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n    DECLARE\n        v_service_period_id uuid;\n        v_service_period_name text;\n        v_max_covers integer;\n        v_max_parties integer;\n        v_booked_covers integer;\n        v_booked_parties integer;\n        v_booking_id uuid;\n        v_booking_record jsonb;\n        v_reference text;\n        v_start_at timestamptz;\n        v_end_at timestamptz;\n        v_timezone text;\n        v_timezone_raw text;\n    BEGIN\n        -- =====================================================\n        -- STEP 1: Idempotency Check\n        -- =====================================================\n        IF p_idempotency_key IS NOT NULL THEN\n            SELECT id INTO v_booking_id \n            FROM bookings \n            WHERE restaurant_id = p_restaurant_id \n                AND idempotency_key = p_idempotency_key\n            LIMIT 1;\n            \n            IF FOUND THEN\n                SELECT to_jsonb(b.*) INTO v_booking_record\n                FROM bookings b \n                WHERE id = v_booking_id;\n                \n                RETURN jsonb_build_object(\n                    'success', true,\n                    'duplicate', true,\n                    'booking', v_booking_record,\n                    'message', 'Booking already exists (idempotency)'\n                );\n            END IF;\n        END IF;\n        \n        -- =====================================================\n        -- STEP 2: Find Applicable Service Period\n        -- =====================================================\n        SELECT sp.id, sp.name INTO v_service_period_id, v_service_period_name\n        FROM restaurant_service_periods sp\n        WHERE sp.restaurant_id = p_restaurant_id\n            AND (sp.day_of_week IS NULL OR sp.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n            AND p_start_time >= sp.start_time\n            AND p_start_time < sp.end_time\n        ORDER BY \n            sp.day_of_week DESC NULLS LAST,\n            sp.start_time ASC\n        LIMIT 1;\n        \n        -- =====================================================\n        -- STEP 3: Get Capacity Rules with Row-Level Lock\n        -- =====================================================\n        SELECT \n            COALESCE(cr.max_covers, 999999) as max_covers,\n            COALESCE(cr.max_parties, 999999) as max_parties\n        INTO v_max_covers, v_max_parties\n        FROM restaurant_capacity_rules cr\n        WHERE cr.restaurant_id = p_restaurant_id\n            AND (cr.service_period_id IS NULL OR cr.service_period_id = v_service_period_id)\n            AND (cr.day_of_week IS NULL OR cr.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n            AND (cr.effective_date IS NULL OR cr.effective_date <= p_booking_date)\n        ORDER BY \n            cr.effective_date DESC NULLS LAST,\n            cr.day_of_week DESC NULLS LAST,\n            cr.service_period_id DESC NULLS LAST\n        LIMIT 1\n        FOR UPDATE NOWAIT;\n        \n        v_max_covers := COALESCE(v_max_covers, 999999);\n        v_max_parties := COALESCE(v_max_parties, 999999);\n        \n        -- =====================================================\n        -- STEP 4: Count Existing Bookings in Same Period\n        -- =====================================================\n        SELECT \n            COALESCE(SUM(b.party_size), 0) as total_covers,\n            COUNT(*) as total_parties\n        INTO v_booked_covers, v_booked_parties\n        FROM bookings b\n        WHERE b.restaurant_id = p_restaurant_id\n            AND b.booking_date = p_booking_date\n            AND b.status NOT IN ('cancelled', 'no_show')\n            AND (\n                v_service_period_id IS NULL\n                OR b.start_time >= (\n                    SELECT start_time FROM restaurant_service_periods WHERE id = v_service_period_id\n                )\n                AND b.start_time < (\n                    SELECT end_time FROM restaurant_service_periods WHERE id = v_service_period_id\n                )\n            );\n        \n        -- =====================================================\n        -- STEP 5: Capacity Validation\n        -- =====================================================\n        IF v_booked_covers + p_party_size > v_max_covers THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'CAPACITY_EXCEEDED',\n                'message', format('Maximum capacity of %s covers exceeded. Currently booked: %s, Requested: %s',\n                    v_max_covers, v_booked_covers, p_party_size),\n                'details', jsonb_build_object(\n                    'maxCovers', v_max_covers,\n                    'bookedCovers', v_booked_covers,\n                    'requestedCovers', p_party_size,\n                    'availableCovers', v_max_covers - v_booked_covers,\n                    'servicePeriod', v_service_period_name\n                )\n            );\n        END IF;\n        \n        IF v_booked_parties + 1 > v_max_parties THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'CAPACITY_EXCEEDED',\n                'message', format('Maximum of %s bookings exceeded for this period. Currently booked: %s',\n                    v_max_parties, v_booked_parties),\n                'details', jsonb_build_object(\n                    'maxParties', v_max_parties,\n                    'bookedParties', v_booked_parties,\n                    'availableParties', v_max_parties - v_booked_parties,\n                    'servicePeriod', v_service_period_name\n                )\n            );\n        END IF;\n        \n        v_reference := public.generate_booking_reference();\n        \n        SELECT timezone INTO v_timezone_raw\n        FROM restaurants\n        WHERE id = p_restaurant_id;\n\n        v_timezone_raw := COALESCE(BTRIM(v_timezone_raw), '');\n\n        IF v_timezone_raw = '' THEN\n            v_timezone := 'Europe/London';\n        ELSE\n            SELECT name INTO v_timezone\n            FROM pg_timezone_names\n            WHERE lower(name) = lower(v_timezone_raw)\n            LIMIT 1;\n\n            IF NOT FOUND OR v_timezone IS NULL THEN\n                v_timezone := 'Europe/London';\n            END IF;\n        END IF;\n        \n        v_start_at := make_timestamptz(\n            EXTRACT(YEAR FROM p_booking_date)::int,\n            EXTRACT(MONTH FROM p_booking_date)::int,\n            EXTRACT(DAY FROM p_booking_date)::int,\n            EXTRACT(HOUR FROM p_start_time)::int,\n            EXTRACT(MINUTE FROM p_start_time)::int,\n            EXTRACT(SECOND FROM p_start_time),\n            v_timezone\n        );\n        \n        v_end_at := make_timestamptz(\n            EXTRACT(YEAR FROM p_booking_date)::int,\n            EXTRACT(MONTH FROM p_booking_date)::int,\n            EXTRACT(DAY FROM p_booking_date)::int,\n            EXTRACT(HOUR FROM p_end_time)::int,\n            EXTRACT(MINUTE FROM p_end_time)::int,\n            EXTRACT(SECOND FROM p_end_time),\n            v_timezone\n        );\n        \n        INSERT INTO bookings (\n            restaurant_id,\n            customer_id,\n            booking_date,\n            start_time,\n            end_time,\n            start_at,\n            end_at,\n            party_size,\n            booking_type,\n            seating_preference,\n            status,\n            reference,\n            customer_name,\n            customer_email,\n            customer_phone,\n            notes,\n            marketing_opt_in,\n            loyalty_points_awarded,\n            source,\n            auth_user_id,\n            idempotency_key,\n            details\n        ) VALUES (\n            p_restaurant_id,\n            p_customer_id,\n            p_booking_date,\n            p_start_time,\n            p_end_time,\n            v_start_at,\n            v_end_at,\n            p_party_size,\n            p_booking_type::booking_type,\n            p_seating_preference::seating_preference_type,\n            'confirmed'::booking_status,\n            v_reference,\n            p_customer_name,\n            p_customer_email,\n            p_customer_phone,\n            p_notes,\n            p_marketing_opt_in,\n            p_loyalty_points_awarded,\n            p_source,\n            p_auth_user_id,\n            p_idempotency_key,\n            jsonb_build_object(\n                'channel', 'api.capacity_safe',\n                'client_request_id', p_client_request_id,\n                'capacity_check', jsonb_build_object(\n                    'service_period_id', v_service_period_id,\n                    'max_covers', v_max_covers,\n                    'booked_covers_before', v_booked_covers,\n                    'booked_covers_after', v_booked_covers + p_party_size\n                ),\n                'timezone', v_timezone,\n                'original_timezone', NULLIF(v_timezone_raw, '')\n            ) || COALESCE(p_details, '{}'::jsonb)\n        )\n        RETURNING id, to_jsonb(bookings.*) INTO v_booking_id, v_booking_record;\n        \n        RETURN jsonb_build_object(\n            'success', true,\n            'duplicate', false,\n            'booking', v_booking_record,\n            'capacity', jsonb_build_object(\n                'servicePeriod', v_service_period_name,\n                'maxCovers', v_max_covers,\n                'bookedCovers', v_booked_covers + p_party_size,\n                'availableCovers', v_max_covers - (v_booked_covers + p_party_size),\n                'utilizationPercent', ROUND(((v_booked_covers + p_party_size)::numeric / v_max_covers) * 100, 1)\n            ),\n            'message', 'Booking created successfully'\n        );\n        \n    EXCEPTION\n        WHEN serialization_failure THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Concurrent booking conflict detected. Please retry.',\n                'retryable', true\n            );\n        \n        WHEN deadlock_detected THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Database deadlock detected. Please retry.',\n                'retryable', true\n            );\n        \n        WHEN lock_not_available THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Capacity rule is currently locked by another transaction. Please retry.',\n                'retryable', true\n            );\n        \n        WHEN OTHERS THEN\n            RAISE WARNING 'Unexpected error in create_booking_with_capacity_check: % %', SQLERRM, SQLSTATE;\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'INTERNAL_ERROR',\n                'message', 'An unexpected error occurred while creating the booking',\n                'retryable', false,\n                'sqlstate', SQLSTATE,\n                'sqlerrm', SQLERRM,\n                'timezone', v_timezone,\n                'original_timezone', NULLIF(v_timezone_raw, '')\n            );\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"create_booking_with_capacity_check\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_customer_id\\" \\"uuid\\", \\"p_booking_date\\" \\"date\\", \\"p_start_time\\" time without time zone, \\"p_end_time\\" time without time zone, \\"p_party_size\\" integer, \\"p_booking_type\\" \\"text\\", \\"p_customer_name\\" \\"text\\", \\"p_customer_email\\" \\"text\\", \\"p_customer_phone\\" \\"text\\", \\"p_seating_preference\\" \\"text\\", \\"p_notes\\" \\"text\\", \\"p_marketing_opt_in\\" boolean, \\"p_idempotency_key\\" \\"text\\", \\"p_source\\" \\"text\\", \\"p_auth_user_id\\" \\"uuid\\", \\"p_client_request_id\\" \\"text\\", \\"p_details\\" \\"jsonb\\", \\"p_loyalty_points_awarded\\" integer) OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"create_booking_with_capacity_check\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_customer_id\\" \\"uuid\\", \\"p_booking_date\\" \\"date\\", \\"p_start_time\\" time without time zone, \\"p_end_time\\" time without time zone, \\"p_party_size\\" integer, \\"p_booking_type\\" \\"text\\", \\"p_customer_name\\" \\"text\\", \\"p_customer_email\\" \\"text\\", \\"p_customer_phone\\" \\"text\\", \\"p_seating_preference\\" \\"text\\", \\"p_notes\\" \\"text\\", \\"p_marketing_opt_in\\" boolean, \\"p_idempotency_key\\" \\"text\\", \\"p_source\\" \\"text\\", \\"p_auth_user_id\\" \\"uuid\\", \\"p_client_request_id\\" \\"text\\", \\"p_details\\" \\"jsonb\\", \\"p_loyalty_points_awarded\\" integer) IS 'Race-safe booking creation with capacity enforcement. Uses SERIALIZABLE isolation and row-level locking to prevent overbooking. Returns JSONB with success/error/booking/capacity data.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"generate_booking_reference\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE\n  chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- excludes 0/O/1/I\n  result text := '';\n  i integer;\nBEGIN\n  FOR i IN 1..10 LOOP\n    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);\n  END LOOP;\n  RETURN result;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"generate_booking_reference\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_or_create_booking_slot\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_slot_date\\" \\"date\\", \\"p_slot_time\\" time without time zone, \\"p_default_capacity\\" integer DEFAULT 999) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\nDECLARE\n    v_slot_id uuid;\n    v_service_period_id uuid;\n    v_capacity integer;\nBEGIN\n    -- Try to find existing slot\n    SELECT id INTO v_slot_id\n    FROM booking_slots\n    WHERE restaurant_id = p_restaurant_id\n        AND slot_date = p_slot_date\n        AND slot_time = p_slot_time;\n    \n    IF FOUND THEN\n        RETURN v_slot_id;\n    END IF;\n    \n    -- Find applicable service period\n    SELECT id INTO v_service_period_id\n    FROM restaurant_service_periods\n    WHERE restaurant_id = p_restaurant_id\n        AND (day_of_week IS NULL OR day_of_week = EXTRACT(DOW FROM p_slot_date)::smallint)\n        AND p_slot_time >= start_time\n        AND p_slot_time < end_time\n    ORDER BY day_of_week DESC NULLS LAST\n    LIMIT 1;\n    \n    -- Get capacity from rules (if exists)\n    SELECT COALESCE(max_covers, p_default_capacity) INTO v_capacity\n    FROM restaurant_capacity_rules\n    WHERE restaurant_id = p_restaurant_id\n        AND (service_period_id IS NULL OR service_period_id = v_service_period_id)\n        AND (day_of_week IS NULL OR day_of_week = EXTRACT(DOW FROM p_slot_date)::smallint)\n        AND (effective_date IS NULL OR effective_date <= p_slot_date)\n    ORDER BY \n        effective_date DESC NULLS LAST,\n        day_of_week DESC NULLS LAST,\n        service_period_id DESC NULLS LAST\n    LIMIT 1;\n    \n    -- Default capacity if no rule found\n    v_capacity := COALESCE(v_capacity, p_default_capacity);\n    \n    -- Create new slot\n    INSERT INTO booking_slots (\n        restaurant_id,\n        slot_date,\n        slot_time,\n        service_period_id,\n        available_capacity,\n        reserved_count\n    ) VALUES (\n        p_restaurant_id,\n        p_slot_date,\n        p_slot_time,\n        v_service_period_id,\n        v_capacity,\n        0\n    )\n    RETURNING id INTO v_slot_id;\n    \n    RETURN v_slot_id;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"get_or_create_booking_slot\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_slot_date\\" \\"date\\", \\"p_slot_time\\" time without time zone, \\"p_default_capacity\\" integer) OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"get_or_create_booking_slot\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_slot_date\\" \\"date\\", \\"p_slot_time\\" time without time zone, \\"p_default_capacity\\" integer) IS 'Get existing slot or create new one with capacity derived from rules. Used for lazy slot creation.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"increment_booking_slot_version\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n    -- Only increment version if reserved_count changed\n    IF OLD.reserved_count IS DISTINCT FROM NEW.reserved_count THEN\n        NEW.version := OLD.version + 1;\n    END IF;\n    RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"increment_booking_slot_version\\"() OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"increment_booking_slot_version\\"() IS 'Automatically increment version column when reserved_count changes (optimistic concurrency control)'","CREATE OR REPLACE FUNCTION \\"public\\".\\"increment_capacity_metrics\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_window_start\\" timestamp with time zone, \\"p_success_delta\\" integer DEFAULT 0, \\"p_conflict_delta\\" integer DEFAULT 0, \\"p_capacity_exceeded_delta\\" integer DEFAULT 0) RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  INSERT INTO public.capacity_metrics_hourly (\n    restaurant_id,\n    window_start,\n    success_count,\n    conflict_count,\n    capacity_exceeded_count\n  )\n  VALUES (\n    p_restaurant_id,\n    date_trunc('hour', p_window_start),\n    GREATEST(p_success_delta, 0),\n    GREATEST(p_conflict_delta, 0),\n    GREATEST(p_capacity_exceeded_delta, 0)\n  )\n  ON CONFLICT (restaurant_id, window_start)\n  DO UPDATE SET\n    success_count = public.capacity_metrics_hourly.success_count + GREATEST(p_success_delta, 0),\n    conflict_count = public.capacity_metrics_hourly.conflict_count + GREATEST(p_conflict_delta, 0),\n    capacity_exceeded_count = public.capacity_metrics_hourly.capacity_exceeded_count + GREATEST(p_capacity_exceeded_delta, 0),\n    updated_at = timezone('utc', now());\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"increment_capacity_metrics\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_window_start\\" timestamp with time zone, \\"p_success_delta\\" integer, \\"p_conflict_delta\\" integer, \\"p_capacity_exceeded_delta\\" integer) OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"increment_capacity_metrics\\"(\\"p_restaurant_id\\" \\"uuid\\", \\"p_window_start\\" timestamp with time zone, \\"p_success_delta\\" integer, \\"p_conflict_delta\\" integer, \\"p_capacity_exceeded_delta\\" integer) IS 'Increment hourly capacity metrics counters with atomic upsert.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"log_table_assignment_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\nBEGIN\n    -- Log to audit_logs table if it exists\n    IF TG_OP = 'INSERT' THEN\n        INSERT INTO audit_logs (entity, entity_id, action, actor, metadata)\n        VALUES (\n            'booking_table_assignment',\n            NEW.id::text,\n            'assigned',\n            NEW.assigned_by::text,\n            jsonb_build_object(\n                'booking_id', NEW.booking_id,\n                'table_id', NEW.table_id,\n                'slot_id', NEW.slot_id\n            )\n        );\n    ELSIF TG_OP = 'DELETE' THEN\n        INSERT INTO audit_logs (entity, entity_id, action, actor, metadata)\n        VALUES (\n            'booking_table_assignment',\n            OLD.id::text,\n            'unassigned',\n            OLD.assigned_by::text,\n            jsonb_build_object(\n                'booking_id', OLD.booking_id,\n                'table_id', OLD.table_id,\n                'slot_id', OLD.slot_id\n            )\n        );\n    END IF;\n    \n    RETURN COALESCE(NEW, OLD);\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"log_table_assignment_change\\"() OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"log_table_assignment_change\\"() IS 'Audit trail for table assignment changes (who assigned what table to which booking)'","CREATE OR REPLACE FUNCTION \\"public\\".\\"on_allocations_refresh\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\n    DECLARE\n      v_table uuid;\n    BEGIN\n      IF TG_OP = 'DELETE' THEN\n        IF OLD.resource_type = 'table' THEN\n          PERFORM public.refresh_table_status(OLD.resource_id);\n        END IF;\n      ELSE\n        IF NEW.resource_type = 'table' THEN\n          PERFORM public.refresh_table_status(NEW.resource_id);\n        END IF;\n      END IF;\n      RETURN NULL;\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"on_allocations_refresh\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"on_booking_status_refresh\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\n    DECLARE\n      v_table_id uuid;\n    BEGIN\n      IF TG_OP <> 'UPDATE' OR NEW.status = OLD.status THEN\n        RETURN NEW;\n      END IF;\n\n      FOR v_table_id IN\n        SELECT table_id\n        FROM public.booking_table_assignments\n        WHERE booking_id = NEW.id\n      LOOP\n        PERFORM public.refresh_table_status(v_table_id);\n      END LOOP;\n\n      RETURN NEW;\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"on_booking_status_refresh\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"refresh_table_status\\"(\\"p_table_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\n    DECLARE\n      v_has_checked_in boolean;\n      v_has_future_or_current boolean;\n    BEGIN\n      IF p_table_id IS NULL THEN\n        RETURN;\n      END IF;\n\n      IF EXISTS (\n        SELECT 1\n        FROM public.allocations a\n        WHERE a.resource_type = 'table'\n          AND a.resource_id = p_table_id\n          AND a.is_maintenance\n          AND a.\\"window\\" @> now()\n      ) THEN\n        UPDATE public.table_inventory\n        SET status = 'out_of_service'\n        WHERE id = p_table_id;\n        RETURN;\n      END IF;\n\n      SELECT EXISTS (\n        SELECT 1\n        FROM public.allocations a\n        JOIN public.bookings b ON b.id = a.booking_id\n        WHERE a.resource_type = 'table'\n          AND a.resource_id = p_table_id\n          AND b.status = 'checked_in'\n          AND a.\\"window\\" @> now()\n      ) INTO v_has_checked_in;\n\n      IF v_has_checked_in THEN\n        UPDATE public.table_inventory\n        SET status = 'occupied'\n        WHERE id = p_table_id\n          AND status <> 'out_of_service';\n        RETURN;\n      END IF;\n\n      SELECT EXISTS (\n        SELECT 1\n        FROM public.allocations a\n        WHERE a.resource_type = 'table'\n          AND a.resource_id = p_table_id\n          AND upper(a.\\"window\\") > now()\n      ) INTO v_has_future_or_current;\n\n      IF v_has_future_or_current THEN\n        UPDATE public.table_inventory\n        SET status = 'reserved'\n        WHERE id = p_table_id\n          AND status NOT IN ('occupied', 'out_of_service');\n      ELSE\n        UPDATE public.table_inventory\n        SET status = 'available'\n        WHERE id = p_table_id\n          AND status <> 'out_of_service';\n      END IF;\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"refresh_table_status\\"(\\"p_table_id\\" \\"uuid\\") OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"set_booking_instants\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE\n  tz text;\n  sh int; sm int; ss double precision;\n  eh int; em int; es double precision;\nBEGIN\n  SELECT timezone INTO tz FROM public.restaurants WHERE id = NEW.restaurant_id;\n\n  sh := EXTRACT(HOUR   FROM NEW.start_time)::int;\n  sm := EXTRACT(MINUTE FROM NEW.start_time)::int;\n  ss := EXTRACT(SECOND FROM NEW.start_time);\n  eh := EXTRACT(HOUR   FROM NEW.end_time)::int;\n  em := EXTRACT(MINUTE FROM NEW.end_time)::int;\n  es := EXTRACT(SECOND FROM NEW.end_time);\n\n  NEW.start_at := make_timestamptz(\n                    EXTRACT(YEAR  FROM NEW.booking_date)::int,\n                    EXTRACT(MONTH FROM NEW.booking_date)::int,\n                    EXTRACT(DAY   FROM NEW.booking_date)::int,\n                    sh, sm, ss, tz\n                  );\n\n  NEW.end_at := make_timestamptz(\n                    EXTRACT(YEAR  FROM NEW.booking_date)::int,\n                    EXTRACT(MONTH FROM NEW.booking_date)::int,\n                    EXTRACT(DAY   FROM NEW.booking_date)::int,\n                    eh, em, es, tz\n               );\n\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"set_booking_instants\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"set_booking_reference\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE ref text;\nBEGIN\n  IF COALESCE(NEW.reference,'') = '' THEN\n    LOOP\n      ref := public.generate_booking_reference();\n      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.bookings WHERE reference = ref);\n    END LOOP;\n    NEW.reference := ref;\n  END IF;\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"set_booking_reference\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"sync_table_adjacency_symmetry\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NOT EXISTS (\n      SELECT 1 FROM public.table_adjacencies\n      WHERE table_a = NEW.table_b AND table_b = NEW.table_a\n    ) THEN\n      IF NEW.table_a::text < NEW.table_b::text THEN\n        INSERT INTO public.table_adjacencies(table_a, table_b)\n        VALUES (NEW.table_b, NEW.table_a)\n        ON CONFLICT DO NOTHING;\n      END IF;\n    END IF;\n    RETURN NEW;\n  ELSIF TG_OP = 'DELETE' THEN\n    DELETE FROM public.table_adjacencies\n    WHERE table_a = OLD.table_b AND table_b = OLD.table_a;\n    RETURN OLD;\n  END IF;\n  RETURN NULL;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"sync_table_adjacency_symmetry\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"unassign_table_from_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\nDECLARE\n    v_deleted boolean;\nBEGIN\n    -- Delete assignment\n    DELETE FROM booking_table_assignments\n    WHERE booking_id = p_booking_id\n        AND table_id = p_table_id;\n    \n    GET DIAGNOSTICS v_deleted = ROW_COUNT;\n    \n    IF v_deleted THEN\n        -- Update table status to available\n        UPDATE table_inventory\n        SET status = 'available'::table_status\n        WHERE id = p_table_id\n            AND NOT EXISTS (\n                -- Keep as reserved if other active bookings exist\n                SELECT 1 FROM booking_table_assignments bta\n                JOIN bookings b ON b.id = bta.booking_id\n                WHERE bta.table_id = p_table_id\n                    AND b.status NOT IN ('cancelled', 'no_show', 'completed')\n            );\n        \n        RETURN true;\n    END IF;\n    \n    RETURN false;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"unassign_table_from_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\") OWNER TO \\"postgres\\"","COMMENT ON FUNCTION \\"public\\".\\"unassign_table_from_booking\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_id\\" \\"uuid\\") IS 'Remove table assignment from booking. Updates table status to available if no other active bookings.'","CREATE OR REPLACE FUNCTION \\"public\\".\\"unassign_tables_atomic\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_ids\\" \\"uuid\\"[] DEFAULT NULL::\\"uuid\\"[], \\"p_merge_group_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"table_id\\" \\"uuid\\", \\"merge_group_id\\" \\"uuid\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    AS $$\n    DECLARE\n      v_target_tables uuid[] := p_table_ids;\n      v_removed RECORD;\n      v_tables_from_group uuid[];\n      v_merge_group_id uuid := p_merge_group_id;\n    BEGIN\n      IF v_target_tables IS NOT NULL THEN\n        SELECT array_agg(DISTINCT table_id)\n        INTO v_target_tables\n        FROM unnest(v_target_tables) AS t(table_id);\n      END IF;\n\n      IF (v_target_tables IS NULL OR array_length(v_target_tables, 1) = 0) THEN\n        IF v_merge_group_id IS NULL THEN\n          RAISE EXCEPTION 'Provide table_ids or merge_group_id to unassign'\n            USING ERRCODE = '23514';\n        END IF;\n\n        SELECT array_agg(table_id)\n        INTO v_tables_from_group\n        FROM public.merge_group_members\n        WHERE merge_group_id = v_merge_group_id;\n\n        v_target_tables := v_tables_from_group;\n      END IF;\n\n      IF v_target_tables IS NULL OR array_length(v_target_tables, 1) = 0 THEN\n        RETURN;\n      END IF;\n\n      FOR v_removed IN\n        DELETE FROM public.booking_table_assignments\n        WHERE booking_id = p_booking_id\n          AND table_id = ANY (v_target_tables)\n        RETURNING table_id, merge_group_id\n      LOOP\n        table_id := v_removed.table_id;\n        merge_group_id := v_removed.merge_group_id;\n        IF v_merge_group_id IS NULL THEN\n          v_merge_group_id := v_removed.merge_group_id;\n        END IF;\n\n        DELETE FROM public.allocations\n        WHERE booking_id = p_booking_id\n          AND resource_type = 'table'\n          AND resource_id = v_removed.table_id;\n\n        UPDATE public.table_inventory ti\n        SET status = 'available'::public.table_status\n        WHERE ti.id = v_removed.table_id\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.booking_table_assignments bta\n            WHERE bta.table_id = v_removed.table_id\n          );\n\n        RETURN NEXT;\n      END LOOP;\n\n      IF v_merge_group_id IS NULL THEN\n        SELECT merge_group_id\n        INTO v_merge_group_id\n        FROM public.booking_table_assignments\n        WHERE booking_id = p_booking_id\n          AND merge_group_id IS NOT NULL\n        LIMIT 1;\n      END IF;\n\n      IF v_merge_group_id IS NOT NULL THEN\n        DELETE FROM public.allocations\n        WHERE booking_id = p_booking_id\n          AND resource_type = 'merge_group'\n          AND resource_id = v_merge_group_id;\n\n        UPDATE public.merge_groups\n        SET dissolved_at = now()\n        WHERE id = v_merge_group_id\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.booking_table_assignments bta\n            WHERE bta.merge_group_id = v_merge_group_id\n          );\n\n        DELETE FROM public.merge_group_members\n        WHERE merge_group_id = v_merge_group_id\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.booking_table_assignments bta\n            WHERE bta.merge_group_id = v_merge_group_id\n          );\n      END IF;\n\n      RETURN;\n    END;\n    $$","ALTER FUNCTION \\"public\\".\\"unassign_tables_atomic\\"(\\"p_booking_id\\" \\"uuid\\", \\"p_table_ids\\" \\"uuid\\"[], \\"p_merge_group_id\\" \\"uuid\\") OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"update_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  NEW.updated_at := now();\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"update_updated_at\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"user_restaurants\\"() RETURNS SETOF \\"uuid\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    AS $$\n  SELECT restaurant_id\n  FROM public.restaurant_memberships\n  WHERE user_id = auth.uid()\n$$","ALTER FUNCTION \\"public\\".\\"user_restaurants\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"user_restaurants_admin\\"() RETURNS SETOF \\"uuid\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT restaurant_id\n  FROM public.restaurant_memberships\n  WHERE user_id = auth.uid()\n    AND role = ANY (ARRAY['owner'::text, 'manager'::text]);\n$$","ALTER FUNCTION \\"public\\".\\"user_restaurants_admin\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"validate_merge_group_members\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE\n  table_ids uuid[];\n  distinct_zones integer;\nBEGIN\n  SELECT array_agg(mgm.table_id)\n  INTO table_ids\n  FROM public.merge_group_members mgm\n  WHERE mgm.merge_group_id = NEW.merge_group_id;\n\n  table_ids := array_append(COALESCE(table_ids, '{}'::uuid[]), NEW.table_id);\n\n  SELECT COUNT(DISTINCT ti.zone_id)\n  INTO distinct_zones\n  FROM public.table_inventory ti\n  WHERE ti.id = ANY(table_ids);\n\n  IF distinct_zones IS NULL OR distinct_zones = 0 THEN\n    RAISE EXCEPTION 'Merge group % references tables that do not exist', NEW.merge_group_id;\n  END IF;\n\n  IF distinct_zones > 1 THEN\n    RAISE EXCEPTION 'Merge group % cannot span multiple zones', NEW.merge_group_id;\n  END IF;\n\n  IF array_length(table_ids, 1) > 1 AND NOT public.are_tables_connected(table_ids) THEN\n    RAISE EXCEPTION 'Merge group % includes tables without adjacency connectivity', NEW.merge_group_id;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"validate_merge_group_members\\"() OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"validate_table_adjacency\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE\n  zone_a uuid;\n  zone_b uuid;\nBEGIN\n  SELECT zone_id INTO zone_a FROM public.table_inventory WHERE id = NEW.table_a;\n  SELECT zone_id INTO zone_b FROM public.table_inventory WHERE id = NEW.table_b;\n\n  IF zone_a IS NULL OR zone_b IS NULL THEN\n    RAISE EXCEPTION 'Tables must belong to zones before adjacency can be created';\n  END IF;\n\n  IF zone_a <> zone_b THEN\n    RAISE EXCEPTION 'Adjacency requires tables to be in the same zone';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","ALTER FUNCTION \\"public\\".\\"validate_table_adjacency\\"() OWNER TO \\"postgres\\"","SET default_tablespace = ''","SET default_table_access_method = \\"heap\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"_migrations\\" (\n    \\"id\\" bigint NOT NULL,\n    \\"name\\" character varying(255) NOT NULL,\n    \\"timestamp\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"status\\" character varying(50) DEFAULT 'applied'::character varying\n)","ALTER TABLE \\"public\\".\\"_migrations\\" OWNER TO \\"postgres\\"","CREATE SEQUENCE IF NOT EXISTS \\"public\\".\\"_migrations_id_seq\\"\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1","ALTER SEQUENCE \\"public\\".\\"_migrations_id_seq\\" OWNER TO \\"postgres\\"","ALTER SEQUENCE \\"public\\".\\"_migrations_id_seq\\" OWNED BY \\"public\\".\\"_migrations\\".\\"id\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"allocations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"booking_id\\" \\"uuid\\",\n    \\"resource_type\\" \\"text\\" NOT NULL,\n    \\"resource_id\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"shadow\\" boolean DEFAULT false NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"window\\" \\"tstzrange\\" NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    \\"is_maintenance\\" boolean DEFAULT false NOT NULL,\n    CONSTRAINT \\"allocations_resource_type_check\\" CHECK ((\\"resource_type\\" = ANY (ARRAY['table'::\\"text\\", 'merge_group'::\\"text\\"])))\n)","ALTER TABLE \\"public\\".\\"allocations\\" OWNER TO \\"postgres\\"","COMMENT ON COLUMN \\"public\\".\\"allocations\\".\\"is_maintenance\\" IS 'True when allocation reserves a table for maintenance/out-of-service windows rather than a booking.'","CREATE TABLE IF NOT EXISTS \\"public\\".\\"allowed_capacities\\" (\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"capacity\\" smallint NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"timezone\\"('utc'::\\"text\\", \\"now\\"()) NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"timezone\\"('utc'::\\"text\\", \\"now\\"()) NOT NULL,\n    CONSTRAINT \\"allowed_capacities_capacity_check\\" CHECK ((\\"capacity\\" > 0))\n)","ALTER TABLE \\"public\\".\\"allowed_capacities\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"analytics_events\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"event_type\\" \\"public\\".\\"analytics_event_type\\" NOT NULL,\n    \\"schema_version\\" \\"text\\" NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"booking_id\\" \\"uuid\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\",\n    \\"emitted_by\\" \\"text\\" DEFAULT 'server'::\\"text\\" NOT NULL,\n    \\"payload\\" \\"jsonb\\" NOT NULL,\n    \\"occurred_at\\" timestamp with time zone NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","ALTER TABLE \\"public\\".\\"analytics_events\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"audit_logs\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"entity\\" \\"text\\" NOT NULL,\n    \\"entity_id\\" \\"text\\" NOT NULL,\n    \\"action\\" \\"text\\" NOT NULL,\n    \\"actor\\" \\"text\\",\n    \\"metadata\\" \\"jsonb\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","ALTER TABLE \\"public\\".\\"audit_logs\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"booking_slots\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"slot_date\\" \\"date\\" NOT NULL,\n    \\"slot_time\\" time without time zone NOT NULL,\n    \\"service_period_id\\" \\"uuid\\",\n    \\"available_capacity\\" integer DEFAULT 0 NOT NULL,\n    \\"reserved_count\\" integer DEFAULT 0 NOT NULL,\n    \\"version\\" integer DEFAULT 1 NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"booking_slots_available_capacity_positive\\" CHECK ((\\"available_capacity\\" >= 0)),\n    CONSTRAINT \\"booking_slots_capacity_valid\\" CHECK (((\\"reserved_count\\" >= 0) AND (\\"reserved_count\\" <= \\"available_capacity\\")))\n)","ALTER TABLE \\"public\\".\\"booking_slots\\" OWNER TO \\"postgres\\"","COMMENT ON TABLE \\"public\\".\\"booking_slots\\" IS 'Pre-materialized time slots with capacity counters for fast availability checks. Created on-demand or pre-generated.'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"slot_date\\" IS 'Date of the slot (e.g., 2025-10-20)'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"slot_time\\" IS 'Time of the slot (e.g., 19:00). Typically 15/30/60 minute intervals.'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"service_period_id\\" IS 'Optional link to service period (lunch/dinner). Null if not applicable.'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"available_capacity\\" IS 'Maximum capacity for this slot (in covers/guests). Derived from capacity rules.'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"reserved_count\\" IS 'Number of covers/guests currently reserved for this slot.'","COMMENT ON COLUMN \\"public\\".\\"booking_slots\\".\\"version\\" IS 'Optimistic locking version. Incremented on each update to prevent race conditions.'","CREATE TABLE IF NOT EXISTS \\"public\\".\\"booking_state_history\\" (\n    \\"id\\" bigint NOT NULL,\n    \\"booking_id\\" \\"uuid\\" NOT NULL,\n    \\"from_status\\" \\"public\\".\\"booking_status\\",\n    \\"to_status\\" \\"public\\".\\"booking_status\\" NOT NULL,\n    \\"changed_by\\" \\"uuid\\",\n    \\"changed_at\\" timestamp with time zone DEFAULT \\"timezone\\"('utc'::\\"text\\", \\"now\\"()) NOT NULL,\n    \\"reason\\" \\"text\\",\n    \\"metadata\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\" NOT NULL\n)","ALTER TABLE \\"public\\".\\"booking_state_history\\" OWNER TO \\"postgres\\"","COMMENT ON TABLE \\"public\\".\\"booking_state_history\\" IS 'Audit history of booking lifecycle transitions.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"booking_id\\" IS 'Booking whose status transitioned.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"from_status\\" IS 'Previous lifecycle status.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"to_status\\" IS 'New lifecycle status.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"changed_by\\" IS 'User who triggered the change (null for system operations).'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"changed_at\\" IS 'UTC timestamp when the transition was recorded.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"reason\\" IS 'Optional human-readable reason for the transition.'","COMMENT ON COLUMN \\"public\\".\\"booking_state_history\\".\\"metadata\\" IS 'Additional structured data describing the transition.'","CREATE SEQUENCE IF NOT EXISTS \\"public\\".\\"booking_state_history_id_seq\\"\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1","ALTER SEQUENCE \\"public\\".\\"booking_state_history_id_seq\\" OWNER TO \\"postgres\\"","ALTER SEQUENCE \\"public\\".\\"booking_state_history_id_seq\\" OWNED BY \\"public\\".\\"booking_state_history\\".\\"id\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"booking_table_assignments\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"booking_id\\" \\"uuid\\" NOT NULL,\n    \\"table_id\\" \\"uuid\\" NOT NULL,\n    \\"slot_id\\" \\"uuid\\",\n    \\"assigned_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"assigned_by\\" \\"uuid\\",\n    \\"notes\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"idempotency_key\\" \\"text\\",\n    \\"merge_group_id\\" \\"uuid\\"\n)","ALTER TABLE \\"public\\".\\"booking_table_assignments\\" OWNER TO \\"postgres\\"","COMMENT ON TABLE \\"public\\".\\"booking_table_assignments\\" IS 'Links bookings to physical tables. A booking can have multiple tables (e.g., party of 10 = 2x 6-tops).'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"booking_id\\" IS 'The booking being assigned a table'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"table_id\\" IS 'The physical table being assigned'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"slot_id\\" IS 'Optional link to the booking slot (for slot-level tracking)'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"assigned_at\\" IS 'When the assignment was made'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"assigned_by\\" IS 'User who made the assignment.'","COMMENT ON COLUMN \\"public\\".\\"booking_table_assignments\\".\\"notes\\" IS 'Optional notes about the assignment (e.g., \\"VIP preferred seating\\")'","CREATE TABLE IF NOT EXISTS \\"public\\".\\"booking_versions\\" (\n    \\"version_id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"booking_id\\" \\"uuid\\" NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"change_type\\" \\"public\\".\\"booking_change_type\\" NOT NULL,\n    \\"changed_by\\" \\"text\\",\n    \\"changed_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"old_data\\" \\"jsonb\\",\n    \\"new_data\\" \\"jsonb\\",\n    \\"created_at\\" timestamp with time zone D