\\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"restaurant_memberships\\" (\n    \\"user_id\\" \\"uuid\\" NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"role\\" \\"text\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"restaurant_memberships_role_check\\" CHECK ((\\"role\\" = ANY (ARRAY['owner'::\\"text\\", 'manager'::\\"text\\", 'host'::\\"text\\", 'server'::\\"text\\"])))\n)","ALTER TABLE \\"public\\".\\"restaurant_memberships\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"restaurant_operating_hours\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"day_of_week\\" smallint,\n    \\"effective_date\\" \\"date\\",\n    \\"opens_at\\" time without time zone,\n    \\"closes_at\\" time without time zone,\n    \\"is_closed\\" boolean DEFAULT false NOT NULL,\n    \\"notes\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"restaurant_operating_hours_scope\\" CHECK (((\\"day_of_week\\" IS NOT NULL) OR (\\"effective_date\\" IS NOT NULL))),\n    CONSTRAINT \\"restaurant_operating_hours_time_order\\" CHECK ((\\"is_closed\\" OR ((\\"opens_at\\" IS NOT NULL) AND (\\"closes_at\\" IS NOT NULL) AND (\\"opens_at\\" < \\"closes_at\\"))))\n)","ALTER TABLE \\"public\\".\\"restaurant_operating_hours\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"restaurant_service_periods\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"name\\" \\"text\\" NOT NULL,\n    \\"day_of_week\\" smallint,\n    \\"start_time\\" time without time zone NOT NULL,\n    \\"end_time\\" time without time zone NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"booking_option\\" \\"text\\" DEFAULT 'drinks'::\\"text\\" NOT NULL,\n    CONSTRAINT \\"restaurant_service_periods_booking_option_check\\" CHECK ((\\"booking_option\\" = ANY (ARRAY['lunch'::\\"text\\", 'dinner'::\\"text\\", 'drinks'::\\"text\\"]))),\n    CONSTRAINT \\"restaurant_service_periods_time_order\\" CHECK ((\\"start_time\\" < \\"end_time\\"))\n)","ALTER TABLE \\"public\\".\\"restaurant_service_periods\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"restaurants\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"name\\" \\"text\\" NOT NULL,\n    \\"slug\\" \\"text\\" NOT NULL,\n    \\"timezone\\" \\"text\\" DEFAULT 'Europe/London'::\\"text\\" NOT NULL,\n    \\"capacity\\" integer,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"contact_email\\" \\"text\\",\n    \\"contact_phone\\" \\"text\\",\n    \\"address\\" \\"text\\",\n    \\"booking_policy\\" \\"text\\",\n    \\"reservation_interval_minutes\\" integer DEFAULT 15 NOT NULL,\n    \\"reservation_default_duration_minutes\\" integer DEFAULT 90 NOT NULL,\n    \\"reservation_last_seating_buffer_minutes\\" integer DEFAULT 120 NOT NULL,\n    \\"is_active\\" boolean DEFAULT true NOT NULL,\n    CONSTRAINT \\"restaurants_capacity_check\\" CHECK (((\\"capacity\\" IS NULL) OR (\\"capacity\\" > 0))),\n    CONSTRAINT \\"restaurants_reservation_default_duration_minutes_check\\" CHECK (((\\"reservation_default_duration_minutes\\" >= 15) AND (\\"reservation_default_duration_minutes\\" <= 300))),\n    CONSTRAINT \\"restaurants_reservation_last_seating_buffer_minutes_check\\" CHECK (((\\"reservation_last_seating_buffer_minutes\\" >= 15) AND (\\"reservation_last_seating_buffer_minutes\\" <= 300))),\n    CONSTRAINT \\"restaurants_reservation_interval_minutes_check\\" CHECK (((\\"reservation_interval_minutes\\" > 0) AND (\\"reservation_interval_minutes\\" <= 180))),\n    CONSTRAINT \\"restaurants_slug_check\\" CHECK ((\\"slug\\" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::\\"text\\"))\n)","ALTER TABLE \\"public\\".\\"restaurants\\" OWNER TO \\"postgres\\"","COMMENT ON COLUMN \\"public\\".\\"restaurants\\".\\"is_active\\" IS 'Indicates whether the restaurant is active and should surface in public experiences.'","CREATE TABLE IF NOT EXISTS \\"public\\".\\"service_policy\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"lunch_start\\" time without time zone DEFAULT '12:00:00'::time without time zone NOT NULL,\n    \\"lunch_end\\" time without time zone DEFAULT '15:00:00'::time without time zone NOT NULL,\n    \\"dinner_start\\" time without time zone DEFAULT '17:00:00'::time without time zone NOT NULL,\n    \\"dinner_end\\" time without time zone DEFAULT '22:00:00'::time without time zone NOT NULL,\n    \\"clean_buffer_minutes\\" smallint DEFAULT 5 NOT NULL,\n    \\"allow_after_hours\\" boolean DEFAULT false NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","ALTER TABLE \\"public\\".\\"service_policy\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"stripe_events\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"event_id\\" \\"text\\" NOT NULL,\n    \\"event_type\\" \\"text\\" NOT NULL,\n    \\"payload\\" \\"jsonb\\" NOT NULL,\n    \\"processed\\" boolean DEFAULT false NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","ALTER TABLE \\"public\\".\\"stripe_events\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"table_adjacencies\\" (\n    \\"table_a\\" \\"uuid\\" NOT NULL,\n    \\"table_b\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"table_adjacencies_not_equal\\" CHECK ((\\"table_a\\" <> \\"table_b\\"))\n)","ALTER TABLE \\"public\\".\\"table_adjacencies\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"table_inventory\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"table_number\\" \\"text\\" NOT NULL,\n    \\"capacity\\" integer NOT NULL,\n    \\"min_party_size\\" integer DEFAULT 1 NOT NULL,\n    \\"max_party_size\\" integer,\n    \\"section\\" \\"text\\",\n    \\"status\\" \\"public\\".\\"table_status\\" DEFAULT 'available'::\\"public\\".\\"table_status\\" NOT NULL,\n    \\"position\\" \\"jsonb\\",\n    \\"notes\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"zone_id\\" \\"uuid\\" NOT NULL,\n    \\"category\\" \\"public\\".\\"table_category\\" NOT NULL,\n    \\"seating_type\\" \\"public\\".\\"table_seating_type\\" DEFAULT 'standard'::\\"public\\".\\"table_seating_type\\" NOT NULL,\n    \\"mobility\\" \\"public\\".\\"table_mobility\\" DEFAULT 'movable'::\\"public\\".\\"table_mobility\\" NOT NULL,\n    \\"active\\" boolean DEFAULT true NOT NULL,\n    CONSTRAINT \\"table_inventory_min_party_positive\\" CHECK ((\\"min_party_size\\" > 0)),\n    CONSTRAINT \\"table_inventory_valid_party_range\\" CHECK (((\\"max_party_size\\" IS NULL) OR (\\"max_party_size\\" >= \\"min_party_size\\")))\n)","ALTER TABLE \\"public\\".\\"table_inventory\\" OWNER TO \\"postgres\\"","COMMENT ON TABLE \\"public\\".\\"table_inventory\\" IS 'Physical restaurant tables with capacity and seating type. Used for table assignment and floor plan visualization.'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"table_number\\" IS 'Display name for the table (e.g., \\"T1\\", \\"Main-5\\", \\"Patio-2\\")'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"capacity\\" IS 'Number of seats at the table'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"min_party_size\\" IS 'Minimum party size for this table (e.g., 2-top only for parties of 2+)'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"max_party_size\\" IS 'Maximum party size for this table (optional, defaults to capacity)'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"section\\" IS 'Section name (e.g., \\"Main Floor\\", \\"Patio\\", \\"Bar Area\\", \\"Private Room\\")'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"status\\" IS 'Current status: available, reserved, occupied, out_of_service'","COMMENT ON COLUMN \\"public\\".\\"table_inventory\\".\\"position\\" IS 'Floor plan position as JSON: {x: number, y: number, rotation?: number} for drag-and-drop UI'","CREATE TABLE IF NOT EXISTS \\"public\\".\\"zones\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"restaurant_id\\" \\"uuid\\" NOT NULL,\n    \\"name\\" \\"text\\" NOT NULL,\n    \\"sort_order\\" smallint DEFAULT 0 NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"zones_name_not_blank\\" CHECK ((\\"char_length\\"(TRIM(BOTH FROM \\"name\\")) > 0))\n)","ALTER TABLE \\"public\\".\\"zones\\" OWNER TO \\"postgres\\"","ALTER TABLE ONLY \\"public\\".\\"_migrations\\" ALTER COLUMN \\"id\\" SET DEFAULT \\"nextval\\"('\\"public\\".\\"_migrations_id_seq\\"'::\\"regclass\\")","ALTER TABLE ONLY \\"public\\".\\"booking_state_history\\" ALTER COLUMN \\"id\\" SET DEFAULT \\"nextval\\"('\\"public\\".\\"booking_state_history_id_seq\\"'::\\"regclass\\")","ALTER TABLE ONLY \\"public\\".\\"_migrations\\"\n    ADD CONSTRAINT \\"_migrations_name_key\\" UNIQUE (\\"name\\")","ALTER TABLE ONLY \\"public\\".\\"_migrations\\"\n    ADD CONSTRAINT \\"_migrations_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"allocations\\"\n    ADD CONSTRAINT \\"allocations_booking_resource_key\\" UNIQUE (\\"booking_id\\", \\"resource_type\\", \\"resource_id\\")","ALTER TABLE ONLY \\"public\\".\\"allocations\\"\n    ADD CONSTRAINT \\"allocations_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"allocations\\"\n    ADD CONSTRAINT \\"allocations_resource_window_excl\\" EXCLUDE USING \\"gist\\" (\\"resource_type\\" WITH =, \\"resource_id\\" WITH =, \\"window\\" WITH &&) DEFERRABLE INITIALLY DEFERRED","ALTER TABLE ONLY \\"public\\".\\"allowed_capacities\\"\n    ADD CONSTRAINT \\"allowed_capacities_pkey\\" PRIMARY KEY (\\"restaurant_id\\", \\"capacity\\")","ALTER TABLE ONLY \\"public\\".\\"analytics_events\\"\n    ADD CONSTRAINT \\"analytics_events_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"audit_logs\\"\n    ADD CONSTRAINT \\"audit_logs_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"booking_slots\\"\n    ADD CONSTRAINT \\"booking_slots_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"booking_slots\\"\n    ADD CONSTRAINT \\"booking_slots_restaurant_slot_key\\" UNIQUE (\\"restaurant_id\\", \\"slot_date\\", \\"slot_time\\")","ALTER TABLE ONLY \\"public\\".\\"booking_state_history\\"\n    ADD CONSTRAINT \\"booking_state_history_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"booking_table_assignments\\"\n    ADD CONSTRAINT \\"booking_table_assignments_booking_table_key\\" UNIQUE (\\"booking_id\\", \\"table_id\\")","ALTER TABLE ONLY \\"public\\".\\"booking_table_assignments\\"\n    ADD CONSTRAINT \\"booking_table_assignments_pkey\\" PRIMARY KEY (\\"id\\")","ALTER TABLE ONLY \\"public\\".\\"booking_versions\\"\n    ADD CONSTRAINT \\"booking_versions_pkey\\" PRIMARY KEY (\\"version_id\\")","ALTER TABLE ONLY \\"public\\".\\"bookings\\"\n    ADD CONSTRAINT \\"bookings_confirmation_token_unique\\" UNIQUE (\\"confirmation_token\\")","ALTER TABLE \\"public\\".\\"bookings\\"\n 