20251020140700	{"-- Adds configurable booking occasion catalogue and enforces FK from restaurant_service_periods.\n\nBEGIN","CREATE TABLE IF NOT EXISTS public.booking_occasions (\n    key text PRIMARY KEY,\n    label text NOT NULL,\n    short_label text NOT NULL,\n    description text,\n    availability jsonb NOT NULL DEFAULT '[]'::jsonb,\n    default_duration_minutes smallint NOT NULL DEFAULT 90,\n    display_order smallint NOT NULL DEFAULT 0,\n    is_active boolean NOT NULL DEFAULT true,\n    created_at timestamptz NOT NULL DEFAULT now(),\n    updated_at timestamptz NOT NULL DEFAULT now()\n)","INSERT INTO public.booking_occasions (key, label, short_label, description, availability, default_duration_minutes, display_order)\nVALUES\n    (\n        'lunch',\n        'Lunch',\n        'Lunch',\n        'Midday dining experience.',\n        '[{\\"kind\\":\\"time_window\\",\\"start\\":\\"11:30\\",\\"end\\":\\"15:30\\"}]'::jsonb,\n        90,\n        10\n    ),\n    (\n        'dinner',\n        'Dinner',\n        'Dinner',\n        'Evening dining service.',\n        '[{\\"kind\\":\\"time_window\\",\\"start\\":\\"17:00\\",\\"end\\":\\"23:00\\"}]'::jsonb,\n        120,\n        20\n    ),\n    (\n        'drinks',\n        'Drinks & Cocktails',\n        'Drinks',\n        'Bar reservations and lounge experiences available throughout operating hours.',\n        '[{\\"kind\\":\\"anytime\\"}]'::jsonb,\n        75,\n        30\n    ),\n    (\n        'christmas_party',\n        'Christmas Party',\n        'Christmas',\n        'Festive group celebration packages available only during December.',\n        '[{\\"kind\\":\\"month_only\\",\\"months\\":[12]}]'::jsonb,\n        150,\n        40\n    ),\n    (\n        'curry_and_carols',\n        'Curry & Carols',\n        'Curry & Carols',\n        'Limited seasonal evenings pairing curry feasts with live carols.',\n        '[{\\"kind\\":\\"specific_dates\\",\\"dates\\":[\\"2025-12-15\\",\\"2025-12-22\\"]}]'::jsonb,\n        150,\n        50\n    )\nON CONFLICT (key) DO UPDATE\nSET\n    label = EXCLUDED.label,\n    short_label = EXCLUDED.short_label,\n    description = EXCLUDED.description,\n    availability = EXCLUDED.availability,\n    default_duration_minutes = EXCLUDED.default_duration_minutes,\n    display_order = EXCLUDED.display_order,\n    is_active = true,\n    updated_at = now()","ALTER TABLE public.restaurant_service_periods\n    DROP CONSTRAINT IF EXISTS restaurant_service_periods_booking_option_check","DO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1\n        FROM information_schema.table_constraints\n        WHERE constraint_name = 'restaurant_service_periods_booking_option_fkey'\n          AND table_name = 'restaurant_service_periods'\n    ) THEN\n        ALTER TABLE public.restaurant_service_periods\n            ADD CONSTRAINT restaurant_service_periods_booking_option_fkey\n            FOREIGN KEY (booking_option)\n            REFERENCES public.booking_occasions (key)\n            ON UPDATE CASCADE\n            ON DELETE RESTRICT;\n    END IF;\nEND $$","ALTER TABLE public.bookings\n    DROP CONSTRAINT IF EXISTS bookings_booking_type_fkey","ALTER TABLE public.bookings\n    ALTER COLUMN booking_type DROP DEFAULT,\n    ALTER COLUMN booking_type TYPE text USING booking_type::text","-- Map legacy booking types to the new catalogue before FK enforcement.\nUPDATE public.restaurant_service_periods\nSET booking_option = 'lunch'\nWHERE booking_option::text IN ('breakfast', 'brunch')","UPDATE public.bookings\nSET booking_type = 'lunch'\nWHERE booking_type::text IN ('breakfast', 'brunch')","-- Clean up any stray null/empty booking types.\nUPDATE public.bookings\nSET booking_type = 'dinner'\nWHERE booking_type IS NULL OR trim(booking_type) = ''","ALTER TABLE public.bookings\n    ADD CONSTRAINT bookings_booking_type_fkey\n        FOREIGN KEY (booking_type)\n        REFERENCES public.booking_occasions (key)\n        ON UPDATE CASCADE\n        ON DELETE RESTRICT","ALTER TABLE public.bookings\n    ALTER COLUMN booking_type SET DEFAULT 'dinner'","DROP TYPE IF EXISTS public.booking_type",COMMIT}	add_booking_occasions_catalog
20251020193000	{"-- Align create_booking_with_capacity_check with booking occasion FK-based schema\n-- and surface diagnostic details for easier debugging.\n\nBEGIN","CREATE OR REPLACE FUNCTION public.create_booking_with_capacity_check(\n    p_restaurant_id uuid,\n    p_customer_id uuid,\n    p_booking_date date,\n    p_start_time time without time zone,\n    p_end_time time without time zone,\n    p_party_size integer,\n    p_booking_type text,\n    p_customer_name text,\n    p_customer_email text,\n    p_customer_phone text,\n    p_seating_preference text,\n    p_notes text DEFAULT NULL::text,\n    p_marketing_opt_in boolean DEFAULT false,\n    p_idempotency_key text DEFAULT NULL::text,\n    p_source text DEFAULT 'api'::text,\n    p_auth_user_id uuid DEFAULT NULL::uuid,\n    p_client_request_id text DEFAULT NULL::text,\n    p_details jsonb DEFAULT '{}'::jsonb,\n    p_loyalty_points_awarded integer DEFAULT 0\n) RETURNS jsonb\n    LANGUAGE plpgsql\n    SECURITY DEFINER\n    SET search_path = 'public'\nAS $$\nDECLARE\n    v_service_period_id uuid;\n    v_service_period_name text;\n    v_max_covers integer;\n    v_max_parties integer;\n    v_booked_covers integer;\n    v_booked_parties integer;\n    v_booking_id uuid;\n    v_booking_record jsonb;\n    v_reference text;\n    v_start_at timestamptz;\n    v_end_at timestamptz;\n    v_timezone text;\n    v_timezone_raw text;\n    v_booking_type bookings.booking_type%TYPE;\n    v_seating_preference bookings.seating_preference%TYPE;\nBEGIN\n    -- =====================================================\n    -- STEP 1: Idempotency Check\n    -- =====================================================\n    IF p_idempotency_key IS NOT NULL THEN\n        SELECT id INTO v_booking_id\n        FROM bookings\n        WHERE restaurant_id = p_restaurant_id\n          AND idempotency_key = p_idempotency_key\n        LIMIT 1;\n\n        IF FOUND THEN\n            SELECT to_jsonb(b.*) INTO v_booking_record\n            FROM bookings b\n            WHERE id = v_booking_id;\n\n            RETURN jsonb_build_object(\n                'success', true,\n                'duplicate', true,\n                'booking', v_booking_record,\n                'message', 'Booking already exists (idempotency)'\n            );\n        END IF;\n    END IF;\n\n    -- =====================================================\n    -- STEP 2: Find Applicable Service Period\n    -- =====================================================\n    SELECT sp.id, sp.name INTO v_service_period_id, v_service_period_name\n    FROM restaurant_service_periods sp\n    WHERE sp.restaurant_id = p_restaurant_id\n      AND (sp.day_of_week IS NULL OR sp.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n      AND p_start_time >= sp.start_time\n      AND p_start_time < sp.end_time\n    ORDER BY\n        sp.day_of_week DESC NULLS LAST,\n        sp.start_time ASC\n    LIMIT 1;\n\n    -- =====================================================\n    -- STEP 3: Get Capacity Rules with Row-Level Lock\n    -- =====================================================\n    SELECT\n        COALESCE(cr.max_covers, 999999) AS max_covers,\n        COALESCE(cr.max_parties, 999999) AS max_parties\n    INTO v_max_covers, v_max_parties\n    FROM restaurant_capacity_rules cr\n    WHERE cr.restaurant_id = p_restaurant_id\n      AND (cr.service_period_id IS NULL OR cr.service_period_id = v_service_period_id)\n      AND (cr.day_of_week IS NULL OR cr.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n      AND (cr.effective_date IS NULL OR cr.effective_date <= p_booking_date)\n    ORDER BY\n        cr.effective_date DESC NULLS LAST,\n        cr.day_of_week DESC NULLS LAST,\n        cr.service_period_id DESC NULLS LAST\n    LIMIT 1\n    FOR UPDATE NOWAIT;\n\n    v_max_covers := COALESCE(v_max_covers, 999999);\n    v_max_parties := COALESCE(v_max_parties, 999999);\n\n    -- =====================================================\n    -- STEP 4: Count Existing Bookings in Same Period\n    -- =====================================================\n    SELECT\n        COALESCE(SUM(b.party_size), 0) AS total_covers,\n        COUNT(*) AS total_parties\n    INTO v_booked_covers, v_booked_parties\n    FROM bookings b\n    WHERE b.restaurant_id = p_restaurant_id\n      AND b.booking_date = p_booking_date\n      AND b.status NOT IN ('cancelled', 'no_show')\n      AND (\n        v_service_period_id IS NULL\n        OR (\n            b.start_time >= (SELECT start_time FROM restaurant_service_periods WHERE id = v_service_period_id)\n            AND b.start_time < (SELECT end_time FROM restaurant_service_periods WHERE id = v_service_period_id)\n        )\n      );\n\n    -- =====================================================\n    -- STEP 5: Capacity Validation\n    -- =====================================================\n    IF v_booked_covers + p_party_size > v_max_covers THEN\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'CAPACITY_EXCEEDED',\n            'message', 'No capacity available for this time slot',\n            'details', jsonb_build_object(\n                'requestedCovers', p_party_size,\n                'maxCovers', v_max_covers,\n                'bookedCovers', v_booked_covers,\n                'availableCovers', GREATEST(v_max_covers - v_booked_covers, 0),\n                'servicePeriod', v_service_period_name,\n                'maxParties', v_max_parties,\n                'bookedParties', v_booked_parties\n            )\n        );\n    END IF;\n\n    IF v_booked_parties + 1 > v_max_parties THEN\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'CAPACITY_EXCEEDED',\n            'message', 'Too many simultaneous parties in this slot',\n            'details', jsonb_build_object(\n                'requestedParties', 1,\n                'maxParties', v_max_parties,\n                'bookedParties', v_booked_parties,\n                'servicePeriod', v_service_period_name,\n                'availableParties', GREATEST(v_max_parties - v_booked_parties, 0)\n            )\n        );\n    END IF;\n\n    v_reference := public.generate_booking_reference();\n\n    SELECT timezone INTO v_timezone_raw\n    FROM restaurants\n    WHERE id = p_restaurant_id;\n\n    v_timezone_raw := COALESCE(BTRIM(v_timezone_raw), '');\n\n    IF v_timezone_raw = '' THEN\n        v_timezone := 'Europe/London';\n    ELSE\n        SELECT name INTO v_timezone\n        FROM pg_timezone_names\n        WHERE lower(name) = lower(v_timezone_raw)\n        LIMIT 1;\n\n        IF NOT FOUND OR v_timezone IS NULL THEN\n            v_timezone := 'Europe/London';\n        END IF;\n    END IF;\n\n    v_start_at := make_timestamptz(\n        EXTRACT(YEAR FROM p_booking_date)::int,\n        EXTRACT(MONTH FROM p_booking_date)::int,\n        EXTRACT(DAY FROM p_booking_date)::int,\n        EXTRACT(HOUR FROM p_start_time)::int,\n        EXTRACT(MINUTE FROM p_start_time)::int,\n        EXTRACT(SECOND FROM p_start_time),\n        v_timezone\n    );\n\n    v_end_at := make_timestamptz(\n        EXTRACT(YEAR FROM p_booking_date)::int,\n        EXTRACT(MONTH FROM p_booking_date)::int,\n        EXTRACT(DAY FROM p_booking_date)::int,\n        EXTRACT(HOUR FROM p_end_time)::int,\n        EXTRACT(MINUTE FROM p_end_time)::int,\n        EXTRACT(SECOND FROM p_end_time),\n        v_timezone\n    );\n\n    v_booking_type := p_booking_type;\n    v_seating_preference := p_seating_preference;\n\n    INSERT INTO bookings (\n        restaurant_id,\n        customer_id,\n        booking_date,\n        start_time,\n        end_time,\n        start_at,\n        end_at,\n        party_size,\n        booking_type,\n        seating_preference,\n        status,\n        reference,\n        customer_name,\n        customer_email,\n        customer_phone,\n        notes,\n        marketing_opt_in,\n        loyalty_points_awarded,\n        source,\n        auth_user_id,\n        idempotency_key,\n        details\n    ) VALUES (\n        p_restaurant_id,\n        p_customer_id,\n        p_booking_date,\n        p_start_time,\n        p_end_time,\n        v_start_at,\n        v_end_at,\n        p_party_size,\n        v_booking_type,\n        v_seating_preference,\n        'confirmed'::booking_status,\n        v_reference,\n        p_customer_name,\n        p_customer_email,\n        p_customer_phone,\n        p_notes,\n        p_marketing_opt_in,\n        p_loyalty_points_awarded,\n        p_source,\n        p_auth_user_id,\n        p_idempotency_key,\n        jsonb_build_object(\n            'channel', 'api.capacity_safe',\n            'client_request_id', p_client_request_id,\n            'capacity_check', jsonb_build_object(\n                'service_period_id', v_service_period_id,\n                'max_covers', v_max_covers,\n                'booked_covers_before', v_booked_covers,\n                'booked_covers_after', v_booked_covers + p_party_size\n            ),\n            'timezone', v_timezone,\n            'original_timezone', NULLIF(v_timezone_raw, '')\n        ) || COALESCE(p_details, '{}'::jsonb)\n    )\n    RETURNING id, to_jsonb(bookings.*) INTO v_booking_id, v_booking_record;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'duplicate', false,\n        'booking', v_booking_record,\n        'capacity', jsonb_build_object(\n            'servicePeriod', v_service_period_name,\n            'maxCovers', v_max_covers,\n            'bookedCovers', v_booked_covers + p_party_size,\n            'availableCovers', GREATEST(v_max_covers - (v_booked_covers + p_party_size), 0),\n            'utilizationPercent', CASE\n                WHEN COALESCE(v_max_covers, 0) = 0 THEN 0\n                ELSE ROUND(((v_booked_covers + p_party_size)::numeric / NULLIF(v_max_covers, 0)) * 100, 1)\n            END\n        ),\n        'message', 'Booking created successfully'\n    );\n\nEXCEPTION\n    WHEN serialization_failure THEN\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'BOOKING_CONFLICT',\n            'message', 'Concurrent booking conflict detected. Please retry.',\n            'retryable', true\n        );\n\n    WHEN deadlock_detected THEN\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'BOOKING_CONFLICT',\n            'message', 'Database deadlock detected. Please retry.',\n            'retryable', true\n        );\n\n    WHEN lock_not_available THEN\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'BOOKING_CONFLICT',\n            'message', 'Capacity rule is currently locked by another transaction. Please retry.',\n            'retryable', true\n        );\n\n    WHEN OTHERS THEN\n        RAISE WARNING 'Unexpected error in create_booking_with_capacity_check: % %', SQLERRM, SQLSTATE;\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'INTERNAL_ERROR',\n            'message', 'An unexpected error occurred while creating the booking',\n            'retryable', false,\n            'details', jsonb_build_object(\n                'sqlstate', SQLSTATE,\n                'sqlerrm', SQLERRM,\n                'timezone', v_timezone,\n                'original_timezone', NULLIF(v_timezone_raw, '')\n            ),\n            'sqlstate', SQLSTATE,\n            'sqlerrm', SQLERRM,\n            'timezone', v_timezone,\n            'original_timezone', NULLIF(v_timezone_raw, '')\n        );\nEND;\n$$",COMMIT}	update_capacity_rpc
20251020232438	{BEGIN,"-- Drop triggers first (before dropping functions they depend on)\nDROP TRIGGER IF EXISTS capacity_metrics_hourly_set_updated_at ON public.capacity_metrics_hourly","DROP TRIGGER IF EXISTS restaurant_capacity_rules_updated_at ON public.restaurant_capacity_rules","-- Now drop capacity-related functions\nDROP FUNCTION IF EXISTS public.capacity_metrics_hourly_updated_at()","DROP FUNCTION IF EXISTS public.increment_capacity_metrics(uuid, timestamptz, integer, integer, integer)","DROP FUNCTION IF EXISTS public.create_booking_with_capacity_check(\n    uuid,\n    uuid,\n    date,\n    time without time zone,\n    time without time zone,\n    integer,\n    text,\n    text,\n    text,\n    text,\n    text,\n    text,\n    boolean,\n    text,\n    text,\n    uuid,\n    text,\n    jsonb,\n    integer\n)","-- Drop capacity tables\nDROP TABLE IF EXISTS public.capacity_metrics_hourly CASCADE","DROP TABLE IF EXISTS public.restaurant_capacity_rules CASCADE","-- Drop capacity-specific enum type\nDROP TYPE IF EXISTS public.capacity_override_type",COMMIT}	remove_capacity_schema
