20251021094503	{"DELETE FROM public.allocations WHERE resource_type = 'merge_group'","ALTER TABLE public.booking_table_assignments\n  DROP CONSTRAINT IF EXISTS booking_table_assignments_merge_group_id_fkey","ALTER TABLE public.booking_table_assignments\n  DROP COLUMN IF EXISTS merge_group_id","DROP TABLE IF EXISTS public.merge_group_members CASCADE","DROP TABLE IF EXISTS public.merge_groups CASCADE","DROP TABLE IF EXISTS public.merge_rules CASCADE"}	cleanup_merge_data
20251021094504	{"DO $migration$\nBEGIN\n  EXECUTE $create$\n    CREATE FUNCTION public.assign_tables_atomic(\n      p_booking_id uuid,\n      p_table_ids uuid[],\n      p_window tstzrange,\n      p_assigned_by uuid DEFAULT NULL,\n      p_idempotency_key text DEFAULT NULL\n    ) RETURNS TABLE(table_id uuid, assignment_id uuid)\n    LANGUAGE plpgsql\n    SECURITY DEFINER\n    AS $function$\n    DECLARE\n      v_booking RECORD;\n      v_restaurant_id uuid;\n      v_target_tables uuid[];\n      v_target_table uuid;\n      v_existing_tables uuid[];\n      v_table RECORD;\n      v_slot_id uuid := NULL;\n      v_now timestamptz := now();\n      v_window tstzrange := p_window;\n      v_assignment_id uuid;\n      v_lock_restaurant int4;\n      v_lock_date int4;\n    BEGIN\n      IF p_table_ids IS NULL OR array_length(p_table_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic requires at least one table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      SELECT array_agg(DISTINCT table_id ORDER BY table_id)\n      INTO v_target_tables\n      FROM unnest(p_table_ids) AS t(table_id);\n\n      IF v_target_tables IS NULL OR array_length(v_target_tables, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic requires at least one valid table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      IF array_length(v_target_tables, 1) > 1 THEN\n        RAISE EXCEPTION 'assign_tables_atomic only supports a single table after merge removal'\n          USING ERRCODE = '23514';\n      END IF;\n\n      v_target_table := v_target_tables[1];\n\n      SELECT *\n      INTO v_booking\n      FROM public.bookings\n      WHERE id = p_booking_id\n      FOR UPDATE;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Booking % not found', p_booking_id\n          USING ERRCODE = 'P0002';\n      END IF;\n\n      v_restaurant_id := v_booking.restaurant_id;\n\n      v_lock_restaurant := hashtext(v_restaurant_id::text);\n      v_lock_date := COALESCE((v_booking.booking_date - DATE '2000-01-01')::int, 0);\n      PERFORM pg_advisory_xact_lock(v_lock_restaurant, v_lock_date);\n\n      IF v_window IS NULL THEN\n        v_window := tstzrange(v_booking.start_at, v_booking.end_at, '[)');\n      END IF;\n\n      IF v_window IS NULL OR lower(v_window) IS NULL OR upper(v_window) IS NULL OR lower(v_window) >= upper(v_window) THEN\n        RAISE EXCEPTION 'Invalid assignment window for booking %', p_booking_id\n          USING ERRCODE = '22000';\n      END IF;\n\n      IF p_idempotency_key IS NOT NULL THEN\n        SELECT array_agg(bta.table_id ORDER BY bta.table_id)\n        INTO v_existing_tables\n        FROM public.booking_table_assignments bta\n        WHERE bta.booking_id = p_booking_id\n          AND bta.idempotency_key = p_idempotency_key;\n\n        IF v_existing_tables IS NOT NULL THEN\n          IF v_existing_tables <> v_target_tables THEN\n            RAISE EXCEPTION 'assign_tables_atomic idempotency key mismatch'\n              USING ERRCODE = 'P0003',\n                    DETAIL = 'Idempotency key reuse detected with a different table id';\n          END IF;\n\n          RETURN QUERY\n            SELECT\n              bta.table_id,\n              bta.id AS assignment_id\n            FROM public.booking_table_assignments bta\n            WHERE bta.booking_id = p_booking_id\n              AND bta.idempotency_key = p_idempotency_key;\n\n          RETURN;\n        END IF;\n      END IF;\n\n      SELECT id, restaurant_id\n      INTO v_table\n      FROM public.table_inventory\n      WHERE id = v_target_table\n      FOR UPDATE;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Table % not found', v_target_table\n          USING ERRCODE = 'P0002';\n      END IF;\n\n      IF v_table.restaurant_id <> v_restaurant_id THEN\n        RAISE EXCEPTION 'Table % belongs to a different restaurant', v_target_table\n          USING ERRCODE = '23503';\n      END IF;\n\n      IF v_booking.booking_date IS NOT NULL AND v_booking.start_time IS NOT NULL THEN\n        SELECT id\n        INTO v_slot_id\n        FROM public.booking_slots\n        WHERE restaurant_id = v_restaurant_id\n          AND slot_date = v_booking.booking_date\n          AND slot_time = v_booking.start_time\n        LIMIT 1;\n\n        IF v_slot_id IS NULL THEN\n          SELECT public.get_or_create_booking_slot(v_restaurant_id, v_booking.booking_date, v_booking.start_time, 999)\n          INTO v_slot_id;\n        END IF;\n      END IF;\n\n      INSERT INTO public.booking_table_assignments (\n        booking_id,\n        table_id,\n        slot_id,\n        assigned_by,\n        idempotency_key\n      ) VALUES (\n        p_booking_id,\n        v_target_table,\n        v_slot_id,\n        p_assigned_by,\n        p_idempotency_key\n      )\n      ON CONFLICT (booking_id, table_id) DO UPDATE\n      SET assigned_by = EXCLUDED.assigned_by,\n          assigned_at = v_now,\n          idempotency_key = COALESCE(EXCLUDED.idempotency_key, public.booking_table_assignments.idempotency_key)\n      RETURNING id INTO v_assignment_id;\n\n      BEGIN\n        INSERT INTO public.allocations (\n          booking_id,\n          restaurant_id,\n          resource_type,\n          resource_id,\n          \\"window\\",\n          created_by,\n          shadow,\n          created_at,\n          updated_at\n        ) VALUES (\n          p_booking_id,\n          v_restaurant_id,\n          'table',\n          v_target_table,\n          v_window,\n          p_assigned_by,\n          false,\n          v_now,\n          v_now\n        )\n        ON CONFLICT ON CONSTRAINT allocations_booking_resource_key DO UPDATE\n        SET \\"window\\" = EXCLUDED.\\"window\\",\n            created_by = EXCLUDED.created_by,\n            updated_at = v_now;\n      EXCEPTION\n        WHEN unique_violation OR exclusion_violation THEN\n          RAISE EXCEPTION 'allocations_no_overlap'\n            USING ERRCODE = 'P0001',\n                  DETAIL = format('Resource %s overlaps requested window for booking %s', v_target_table, p_booking_id);\n      END;\n\n      UPDATE public.table_inventory\n      SET status = 'reserved'::public.table_status\n      WHERE id = v_target_table;\n\n      table_id := v_target_table;\n      assignment_id := v_assignment_id;\n      RETURN NEXT;\n    END;\n    $function$\n  $create$;\n\n  EXECUTE $alter$\n    ALTER FUNCTION public.assign_tables_atomic(uuid, uuid[], tstzrange, uuid, text) OWNER TO postgres\n  $alter$;\n\n  EXECUTE $grant$\n    GRANT ALL ON FUNCTION public.assign_tables_atomic(uuid, uuid[], tstzrange, uuid, text) TO service_role\n  $grant$;\nEND;\n$migration$"}	recreate_assign_tables_atomic
20251021094505	{"DO $migration$\nBEGIN\n  EXECUTE $create$\n    CREATE FUNCTION public.unassign_tables_atomic(\n      p_booking_id uuid,\n      p_table_ids uuid[] DEFAULT NULL\n    ) RETURNS TABLE(table_id uuid)\n    LANGUAGE plpgsql\n    SECURITY DEFINER\n    AS $function$\n    DECLARE\n      v_target_tables uuid[] := p_table_ids;\n      v_removed RECORD;\n    BEGIN\n      IF v_target_tables IS NOT NULL THEN\n        SELECT array_agg(DISTINCT table_id)\n        INTO v_target_tables\n        FROM unnest(v_target_tables) AS t(table_id);\n      ELSE\n        SELECT array_agg(table_id)\n        INTO v_target_tables\n        FROM public.booking_table_assignments\n        WHERE booking_id = p_booking_id;\n      END IF;\n\n      IF v_target_tables IS NULL OR array_length(v_target_tables, 1) = 0 THEN\n        RETURN;\n      END IF;\n\n      FOR v_removed IN\n        DELETE FROM public.booking_table_assignments\n        WHERE booking_id = p_booking_id\n          AND table_id = ANY (v_target_tables)\n        RETURNING table_id\n      LOOP\n        table_id := v_removed.table_id;\n\n        DELETE FROM public.allocations\n        WHERE booking_id = p_booking_id\n          AND resource_type = 'table'\n          AND resource_id = v_removed.table_id;\n\n        UPDATE public.table_inventory ti\n        SET status = 'available'::public.table_status\n        WHERE ti.id = v_removed.table_id\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.booking_table_assignments bta\n            WHERE bta.table_id = v_removed.table_id\n          );\n\n        RETURN NEXT;\n      END LOOP;\n\n      RETURN;\n    END;\n    $function$\n  $create$;\n\n  EXECUTE $alter$\n    ALTER FUNCTION public.unassign_tables_atomic(uuid, uuid[]) OWNER TO postgres\n  $alter$;\n\n  EXECUTE $grant$\n    GRANT ALL ON FUNCTION public.unassign_tables_atomic(uuid, uuid[]) TO service_role\n  $grant$;\nEND;\n$migration$"}	recreate_unassign_tables_atomic
20251021152000	{"-- Introduce transactional update RPC with capacity enforcement\nDO $migration$\nBEGIN\n  EXECUTE $create$\n    CREATE OR REPLACE FUNCTION public.update_booking_with_capacity_check(\n        p_booking_id uuid,\n        p_restaurant_id uuid,\n        p_customer_id uuid,\n        p_booking_date date,\n        p_start_time time without time zone,\n        p_end_time time without time zone,\n        p_party_size integer,\n        p_booking_type text,\n        p_customer_name text,\n        p_customer_email text,\n        p_customer_phone text,\n        p_seating_preference text,\n        p_notes text DEFAULT NULL::text,\n        p_marketing_opt_in boolean DEFAULT false,\n        p_auth_user_id uuid DEFAULT NULL::uuid,\n        p_client_request_id text DEFAULT NULL::text,\n        p_details jsonb DEFAULT '{}'::jsonb,\n        p_loyalty_points_awarded integer DEFAULT 0,\n        p_source text DEFAULT 'api'::text\n    ) RETURNS jsonb\n        LANGUAGE plpgsql\n        SECURITY DEFINER\n        SET search_path = 'public'\n    AS $function$\n    DECLARE\n        v_existing bookings%ROWTYPE;\n        v_service_period_id uuid;\n        v_service_period_name text;\n        v_max_covers integer;\n        v_max_parties integer;\n        v_booked_covers integer;\n        v_booked_parties integer;\n        v_timezone_raw text;\n        v_timezone text;\n        v_start_at timestamptz;\n        v_end_at timestamptz;\n        v_booking_record jsonb;\n        v_booking_type bookings.booking_type%TYPE;\n        v_seating_preference bookings.seating_preference%TYPE;\n    BEGIN\n        SELECT * INTO v_existing\n        FROM bookings\n        WHERE id = p_booking_id\n          AND restaurant_id = p_restaurant_id\n        FOR UPDATE;\n\n        IF NOT FOUND THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'INVALID_PARAMS',\n                'message', 'Booking not found for update'\n            );\n        END IF;\n\n        SELECT sp.id, sp.name INTO v_service_period_id, v_service_period_name\n        FROM restaurant_service_periods sp\n        WHERE sp.restaurant_id = p_restaurant_id\n          AND (sp.day_of_week IS NULL OR sp.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n          AND p_start_time >= sp.start_time\n          AND p_start_time < sp.end_time\n        ORDER BY\n            sp.day_of_week DESC NULLS LAST,\n            sp.start_time ASC\n        LIMIT 1;\n\n        SELECT\n            COALESCE(cr.max_covers, 999999) AS max_covers,\n            COALESCE(cr.max_parties, 999999) AS max_parties\n        INTO v_max_covers, v_max_parties\n        FROM restaurant_capacity_rules cr\n        WHERE cr.restaurant_id = p_restaurant_id\n          AND (cr.service_period_id IS NULL OR cr.service_period_id = v_service_period_id)\n          AND (cr.day_of_week IS NULL OR cr.day_of_week = EXTRACT(DOW FROM p_booking_date)::smallint)\n          AND (cr.effective_date IS NULL OR cr.effective_date <= p_booking_date)\n        ORDER BY\n            cr.effective_date DESC NULLS LAST,\n            cr.day_of_week DESC NULLS LAST,\n            cr.service_period_id DESC NULLS LAST\n        LIMIT 1\n        FOR UPDATE NOWAIT;\n\n        v_max_covers := COALESCE(v_max_covers, 999999);\n        v_max_parties := COALESCE(v_max_parties, 999999);\n\n        SELECT\n            COALESCE(SUM(b.party_size), 0) AS total_covers,\n            COUNT(*) AS total_parties\n        INTO v_booked_covers, v_booked_parties\n        FROM bookings b\n        WHERE b.restaurant_id = p_restaurant_id\n          AND b.booking_date = p_booking_date\n          AND b.status NOT IN ('cancelled', 'no_show')\n          AND b.id <> p_booking_id\n          AND (\n            v_service_period_id IS NULL\n            OR (\n                b.start_time >= (SELECT start_time FROM restaurant_service_periods WHERE id = v_service_period_id)\n                AND b.start_time < (SELECT end_time FROM restaurant_service_periods WHERE id = v_service_period_id)\n            )\n          );\n\n        IF v_booked_covers + p_party_size > v_max_covers THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'CAPACITY_EXCEEDED',\n                'message', 'No capacity available for this time slot',\n                'details', jsonb_build_object(\n                    'requestedCovers', p_party_size,\n                    'maxCovers', v_max_covers,\n                    'bookedCovers', v_booked_covers,\n                    'availableCovers', GREATEST(v_max_covers - v_booked_covers, 0),\n                    'servicePeriod', v_service_period_name,\n                    'maxParties', v_max_parties,\n                    'bookedParties', v_booked_parties\n                )\n            );\n        END IF;\n\n        IF v_booked_parties + 1 > v_max_parties THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'CAPACITY_EXCEEDED',\n                'message', 'Too many simultaneous parties in this slot',\n                'details', jsonb_build_object(\n                    'requestedParties', 1,\n                    'maxParties', v_max_parties,\n                    'bookedParties', v_booked_parties,\n                    'servicePeriod', v_service_period_name,\n                    'availableParties', GREATEST(v_max_parties - v_booked_parties, 0)\n                )\n            );\n        END IF;\n\n        SELECT timezone INTO v_timezone_raw\n        FROM restaurants\n        WHERE id = p_restaurant_id;\n\n        v_timezone_raw := COALESCE(BTRIM(v_timezone_raw), '');\n\n        IF v_timezone_raw = '' THEN\n            v_timezone := 'Europe/London';\n        ELSE\n            SELECT name INTO v_timezone\n            FROM pg_timezone_names\n            WHERE lower(name) = lower(v_timezone_raw)\n            LIMIT 1;\n\n            IF NOT FOUND OR v_timezone IS NULL THEN\n                v_timezone := 'Europe/London';\n            END IF;\n        END IF;\n\n        v_start_at := make_timestamptz(\n            EXTRACT(YEAR FROM p_booking_date)::int,\n            EXTRACT(MONTH FROM p_booking_date)::int,\n            EXTRACT(DAY FROM p_booking_date)::int,\n            EXTRACT(HOUR FROM p_start_time)::int,\n            EXTRACT(MINUTE FROM p_start_time)::int,\n            EXTRACT(SECOND FROM p_start_time),\n            v_timezone\n        );\n\n        v_end_at := make_timestamptz(\n            EXTRACT(YEAR FROM p_booking_date)::int,\n            EXTRACT(MONTH FROM p_booking_date)::int,\n            EXTRACT(DAY FROM p_booking_date)::int,\n            EXTRACT(HOUR FROM p_end_time)::int,\n            EXTRACT(MINUTE FROM p_end_time)::int,\n            EXTRACT(SECOND FROM p_end_time),\n            v_timezone\n        );\n\n        v_booking_type := p_booking_type;\n        v_seating_preference := p_seating_preference;\n\n        UPDATE bookings\n        SET\n            booking_date = p_booking_date,\n            start_time = p_start_time,\n            end_time = p_end_time,\n            start_at = v_start_at,\n            end_at = v_end_at,\n            party_size = p_party_size,\n            booking_type = v_booking_type,\n            seating_preference = v_seating_preference,\n            customer_name = p_customer_name,\n            customer_email = p_customer_email,\n            customer_phone = p_customer_phone,\n            notes = p_notes,\n            marketing_opt_in = p_marketing_opt_in,\n            customer_id = p_customer_id,\n            auth_user_id = COALESCE(p_auth_user_id, v_existing.auth_user_id),\n            client_request_id = COALESCE(p_client_request_id, v_existing.client_request_id),\n            loyalty_points_awarded = COALESCE(p_loyalty_points_awarded, v_existing.loyalty_points_awarded),\n            source = COALESCE(p_source, v_existing.source),\n            details = COALESCE(v_existing.details, '{}'::jsonb)\n                || COALESCE(p_details, '{}'::jsonb)\n                || jsonb_build_object(\n                    'channel', 'api.capacity_safe',\n                    'client_request_id', COALESCE(p_client_request_id, v_existing.client_request_id),\n                    'capacity_check', jsonb_build_object(\n                        'service_period_id', v_service_period_id,\n                        'max_covers', v_max_covers,\n                        'booked_covers_before', v_booked_covers,\n                        'booked_covers_after', v_booked_covers + p_party_size\n                    ),\n                    'timezone', v_timezone,\n                    'original_timezone', NULLIF(v_timezone_raw, '')\n                )\n        WHERE id = p_booking_id\n        RETURNING to_jsonb(bookings.*) INTO v_booking_record;\n\n        RETURN jsonb_build_object(\n            'success', true,\n            'booking', v_booking_record,\n            'capacity', jsonb_build_object(\n                'servicePeriod', v_service_period_name,\n                'maxCovers', v_max_covers,\n                'bookedCovers', v_booked_covers + p_party_size,\n                'availableCovers', GREATEST(v_max_covers - (v_booked_covers + p_party_size), 0),\n                'utilizationPercent', CASE\n                    WHEN COALESCE(v_max_covers, 0) = 0 THEN 0\n                    ELSE ROUND(((v_booked_covers + p_party_size)::numeric / NULLIF(v_max_covers, 0)) * 100, 1)\n                END\n            ),\n            'message', 'Booking updated successfully'\n        );\n\n    EXCEPTION\n        WHEN serialization_failure THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Concurrent booking conflict detected. Please retry.',\n                'retryable', true\n            );\n        WHEN deadlock_detected THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Database deadlock detected. Please retry.',\n                'retryable', true\n            );\n        WHEN lock_not_available THEN\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'BOOKING_CONFLICT',\n                'message', 'Capacity rule is currently locked by another transaction. Please retry.',\n                'retryable', true\n            );\n        WHEN OTHERS THEN\n            RAISE WARNING 'Unexpected error in update_booking_with_capacity_check: % %', SQLERRM, SQLSTATE;\n            RETURN jsonb_build_object(\n                'success', false,\n                'error', 'INTERNAL_ERROR',\n                'message', 'An unexpected error occurred while updating the booking',\n                'retryable', false,\n                'details', jsonb_build_object(\n                    'sqlstate', SQLSTATE,\n                    'sqlerrm', SQLERRM,\n                    'timezone', v_timezone,\n                    'original_timezone', NULLIF(v_timezone_raw, '')\n                ),\n                'sqlstate', SQLSTATE,\n                'sqlerrm', SQLERRM,\n                'timezone', v_timezone,\n                'original_timezone', NULLIF(v_timezone_raw, '')\n            );\n    END;\n    $function$\n  $create$;\n\n  EXECUTE $grant_service$\n    GRANT ALL ON FUNCTION public.update_booking_with_capacity_check(\n        uuid,\n        uuid,\n        uuid,\n        date,\n        time without time zone,\n        time without time zone,\n        integer,\n        text,\n        text,\n        text,\n        text,\n        text,\n        text,\n        boolean,\n        uuid,\n        text,\n        jsonb,\n        integer,\n        text\n    ) TO service_role\n  $grant_service$;\n\n  EXECUTE $grant_authenticated$\n    GRANT ALL ON FUNCTION public.update_booking_with_capacity_check(\n        uuid,\n        uuid,\n        uuid,\n        date,\n        time without time zone,\n        time without time zone,\n        integer,\n        text,\n        text,\n        text,\n        text,\n        text,\n        text,\n        boolean,\n        uuid,\n        text,\n        jsonb,\n        integer,\n        text\n    ) TO authenticated\n  $grant_authenticated$;\n\n  EXECUTE $grant_anon$\n    GRANT ALL ON FUNCTION public.update_booking_with_capacity_check(\n        uuid,\n        uuid,\n        uuid,\n        date,\n        time without time zone,\n        time without time zone,\n        integer,\n        text,\n        text,\n        text,\n        text,\n        text,\n        text,\n        boolean,\n        uuid,\n        text,\n        jsonb,\n        integer,\n        text\n    ) TO anon\n  $grant_anon$;\nEND;\n$migration$"}	add_update_booking_capacity_rpc
20251022224206	{"DO $migration$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_schema = 'public'\n      AND table_name = 'restaurants'\n      AND column_name = 'reservation_last_seating_buffer_minutes'\n  ) THEN\n    EXECUTE $add_column$\n      ALTER TABLE public.restaurants\n        ADD COLUMN reservation_last_seating_buffer_minutes integer NOT NULL DEFAULT 120\n    $add_column$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'restaurants_reservation_last_seating_buffer_minutes_check'\n      AND conrelid = 'public.restaurants'::regclass\n  ) THEN\n    EXECUTE $add_constraint$\n      ALTER TABLE public.restaurants\n        ADD CONSTRAINT restaurants_reservation_last_seating_buffer_minutes_check\n          CHECK (\n              reservation_last_seating_buffer_minutes >= 15\n              AND reservation_last_seating_buffer_minutes <= 300\n          )\n    $add_constraint$;\n  END IF;\n\n  EXECUTE $comment$\n    COMMENT ON COLUMN public.restaurants.reservation_last_seating_buffer_minutes IS\n      'Minimum minutes before closing when the final reservation may start.'\n  $comment$;\nEND;\n$migration$"}	add_last_seating_buffer
20251026104600	{"-- Ensure observability_events exists for selector telemetry + audit logging.\n-- +goose Up\nDO $migration$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'observability_events'\n  ) THEN\n    EXECUTE $create_table$\n      CREATE TABLE public.observability_events (\n        id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n        created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n        source text NOT NULL,\n        event_type text NOT NULL,\n        severity text NOT NULL DEFAULT 'info',\n        context jsonb,\n        restaurant_id uuid,\n        booking_id uuid\n      )\n    $create_table$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'observability_events_severity_check'\n      AND conrelid = 'public.observability_events'::regclass\n  ) THEN\n    EXECUTE $add_severity_check$\n      ALTER TABLE public.observability_events\n        ADD CONSTRAINT observability_events_severity_check\n          CHECK (\n            severity = ANY (ARRAY['info'::text, 'warning'::text, 'error'::text, 'critical'::text])\n          )\n    $add_severity_check$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'observability_events'\n      AND constraint_name = 'observability_events_booking_id_fkey'\n  ) THEN\n    EXECUTE $add_booking_fk$\n      ALTER TABLE public.observability_events\n        ADD CONSTRAINT observability_events_booking_id_fkey\n          FOREIGN KEY (booking_id)\n          REFERENCES public.bookings(id)\n          ON DELETE SET NULL\n    $add_booking_fk$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'observability_events'\n      AND constraint_name = 'observability_events_restaurant_id_fkey'\n  ) THEN\n    EXECUTE $add_restaurant_fk$\n      ALTER TABLE public.observability_events\n        ADD CONSTRAINT observability_events_restaurant_id_fkey\n          FOREIGN KEY (restaurant_id)\n          REFERENCES public.restaurants(id)\n          ON DELETE SET NULL\n    $add_restaurant_fk$;\n  END IF;\n\n  EXECUTE $set_table_comment$\n    COMMENT ON TABLE public.observability_events IS\n      'Write-ahead observability log for allocator + booking workflows. Stores structured context for downstream analysis.'\n  $set_table_comment$;\n\n  EXECUTE $set_column_comment$\n    COMMENT ON COLUMN public.observability_events.context IS\n      'Structured JSON payload describing telemetry context (selectors, actors, diagnostics).'\n  $set_column_comment$;\n\n  CREATE INDEX IF NOT EXISTS observability_events_created_at_idx\n    ON public.observability_events (created_at DESC);\n\n  CREATE INDEX IF NOT EXISTS observability_events_source_idx\n    ON public.observability_events (source);\n\n  CREATE INDEX IF NOT EXISTS observability_events_booking_idx\n    ON public.observability_events (booking_id);\nEND;\n$migration$","-- +goose Down\nDO $migration$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'observability_events'\n  ) THEN\n    EXECUTE 'DROP TABLE public.observability_events CASCADE';\n  END IF;\nEND;\n$migration$"}	add_observability_events
20251026104700	{"-- Introduce table_holds + table_hold_members to back allocator reservations.\n-- +goose Up\nDO $migration$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n  ) THEN\n    EXECUTE $create_holds$\n      CREATE TABLE public.table_holds (\n        id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n        restaurant_id uuid NOT NULL,\n        booking_id uuid,\n        zone_id uuid NOT NULL,\n        start_at timestamptz NOT NULL,\n        end_at timestamptz NOT NULL,\n        expires_at timestamptz NOT NULL,\n        created_by uuid,\n        created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n        updated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n        metadata jsonb,\n        CONSTRAINT table_holds_window_check CHECK (start_at < end_at)\n      )\n    $create_holds$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n      AND constraint_name = 'table_holds_restaurant_id_fkey'\n  ) THEN\n    EXECUTE $add_restaurant_fk$\n      ALTER TABLE public.table_holds\n        ADD CONSTRAINT table_holds_restaurant_id_fkey\n          FOREIGN KEY (restaurant_id)\n          REFERENCES public.restaurants(id)\n          ON DELETE CASCADE\n    $add_restaurant_fk$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n      AND constraint_name = 'table_holds_booking_id_fkey'\n  ) THEN\n    EXECUTE $add_booking_fk$\n      ALTER TABLE public.table_holds\n        ADD CONSTRAINT table_holds_booking_id_fkey\n          FOREIGN KEY (booking_id)\n          REFERENCES public.bookings(id)\n          ON DELETE SET NULL\n    $add_booking_fk$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n      AND constraint_name = 'table_holds_zone_id_fkey'\n  ) THEN\n    EXECUTE $add_zone_fk$\n      ALTER TABLE public.table_holds\n        ADD CONSTRAINT table_holds_zone_id_fkey\n          FOREIGN KEY (zone_id)\n          REFERENCES public.zones(id)\n          ON DELETE CASCADE\n    $add_zone_fk$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n      AND constraint_name = 'table_holds_created_by_fkey'\n  ) THEN\n    EXECUTE $add_created_by_fk$\n      ALTER TABLE public.table_holds\n        ADD CONSTRAINT table_holds_created_by_fkey\n          FOREIGN KEY (created_by)\n          REFERENCES auth.users(id)\n          ON DELETE SET NULL\n    $add_created_by_fk$;\n  END IF;\n\n  EXECUTE $comment_holds$\n    COMMENT ON TABLE public.table_holds IS\n      'Ephemeral table reservations to guard allocations during quoting/confirmation flows.'\n  $comment_holds$;\n\n  CREATE INDEX IF NOT EXISTS table_holds_expires_at_idx\n    ON public.table_holds (expires_at);\n\n  CREATE INDEX IF NOT EXISTS table_holds_zone_start_idx\n    ON public.table_holds (zone_id, start_at);\n\n  CREATE INDEX IF NOT EXISTS table_holds_booking_idx\n    ON public.table_holds (booking_id);\n\n  -- Members --------------------------------------------------------------\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'table_hold_members'\n  ) THEN\n    EXECUTE $create_members$\n      CREATE TABLE public.table_hold_members (\n        id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n        hold_id uuid NOT NULL,\n        table_id uuid NOT NULL,\n        created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n        UNIQUE (hold_id, table_id)\n      )\n    $create_members$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_hold_members'\n      AND constraint_name = 'table_hold_members_hold_id_fkey'\n  ) THEN\n    EXECUTE $add_hold_fk$\n      ALTER TABLE public.table_hold_members\n        ADD CONSTRAINT table_hold_members_hold_id_fkey\n          FOREIGN KEY (hold_id)\n          REFERENCES public.table_holds(id)\n          ON DELETE CASCADE\n    $add_hold_fk$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'table_hold_members'\n      AND constraint_name = 'table_hold_members_table_id_fkey'\n  ) THEN\n    EXECUTE $add_table_fk$\n      ALTER TABLE public.table_hold_members\n        ADD CONSTRAINT table_hold_members_table_id_fkey\n          FOREIGN KEY (table_id)\n          REFERENCES public.table_inventory(id)\n          ON DELETE RESTRICT\n    $add_table_fk$;\n  END IF;\n\n  CREATE INDEX IF NOT EXISTS table_hold_members_table_idx\n    ON public.table_hold_members (table_id);\nEND;\n$migration$","-- +goose Down\nDO $migration$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'table_hold_members'\n  ) THEN\n    EXECUTE 'DROP TABLE public.table_hold_members';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'table_holds'\n  ) THEN\n    EXECUTE 'DROP TABLE public.table_holds';\n  END IF;\nEND;\n$migration$"}	add_table_holds
20251026104800	{"-- Reintroduce merge_group_id on booking_table_assignments linking to allocations.\n-- +goose Up\nDO $migration$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_schema = 'public'\n      AND table_name = 'booking_table_assignments'\n      AND column_name = 'merge_group_id'\n  ) THEN\n    EXECUTE $add_column$\n      ALTER TABLE public.booking_table_assignments\n        ADD COLUMN merge_group_id uuid\n    $add_column$;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'booking_table_assignments'\n      AND constraint_name = 'booking_table_assignments_merge_group_id_fkey'\n  ) THEN\n    EXECUTE $add_fk$\n      ALTER TABLE public.booking_table_assignments\n        ADD CONSTRAINT booking_table_assignments_merge_group_id_fkey\n          FOREIGN KEY (merge_group_id)\n          REFERENCES public.allocations(id)\n          ON DELETE SET NULL\n    $add_fk$;\n  END IF;\n\n  CREATE INDEX IF NOT EXISTS booking_table_assignments_merge_group_idx\n    ON public.booking_table_assignments (merge_group_id);\nEND;\n$migration$","-- +goose Down\nDO $migration$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_indexes\n    WHERE schemaname = 'public'\n      AND tablename = 'booking_table_assignments'\n      AND indexname = 'booking_table_assignments_merge_group_idx'\n  ) THEN\n    EXECUTE 'DROP INDEX public.booking_table_assignments_merge_group_idx';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.constraint_column_usage\n    WHERE table_schema = 'public'\n      AND table_name = 'booking_table_assignments'\n      AND constraint_name = 'booking_table_assignments_merge_group_id_fkey'\n  ) THEN\n    EXECUTE 'ALTER TABLE public.booking_table_assignments DROP CONSTRAINT booking_table_assignments_merge_group_id_fkey';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_schema = 'public'\n      AND table_name = 'booking_table_assignments'\n      AND column_name = 'merge_group_id'\n  ) THEN\n    EXECUTE 'ALTER TABLE public.booking_table_assignments DROP COLUMN merge_group_id';\n  END IF;\nEND;\n$migration$"}	booking_table_assignments_group
20251026104900	{"-- Allow allocations.resource_type to track hold mirrors.\n-- +goose Up\nDO $migration$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'allocations_resource_type_check'\n      AND conrelid = 'public.allocations'::regclass\n  ) THEN\n    EXECUTE 'ALTER TABLE public.allocations DROP CONSTRAINT allocations_resource_type_check';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'allocations_resource_type_check'\n      AND conrelid = 'public.allocations'::regclass\n  ) THEN\n    EXECUTE $add_check$\n      ALTER TABLE public.allocations\n        ADD CONSTRAINT allocations_resource_type_check\n          CHECK (resource_type = ANY (ARRAY['table'::text, 'hold'::text, 'merge_group'::text]))\n    $add_check$;\n  END IF;\nEND;\n$migration$","-- +goose Down\nDO $migration$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'allocations_resource_type_check'\n      AND conrelid = 'public.allocations'::regclass\n  ) THEN\n    EXECUTE 'ALTER TABLE public.allocations DROP CONSTRAINT allocations_resource_type_check';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'allocations_resource_type_check'\n      AND conrelid = 'public.allocations'::regclass\n  ) THEN\n    EXECUTE $restore_check$\n      ALTER TABLE public.allocations\n        ADD CONSTRAINT allocations_resource_type_check\n          CHECK (resource_type = ANY (ARRAY['table'::text, 'merge_group'::text]))\n    $restore_check$;\n  END IF;\nEND;\n$migration$"}	adjust_allocations_types
20251026105000	{"-- Introduce assign_tables_atomic_v2 with per-zone locking, idempotency ledger, and hold awareness.\nDO $migration$\nDECLARE\nBEGIN\n  -- Create idempotency ledger if absent.\n  IF NOT EXISTS (\n    SELECT 1\n    FROM information_schema.tables\n    WHERE table_schema = 'public'\n      AND table_name = 'booking_assignment_idempotency'\n  ) THEN\n    EXECUTE $create_ledger$\n      CREATE TABLE public.booking_assignment_idempotency (\n        booking_id uuid NOT NULL,\n        idempotency_key text NOT NULL,\n        table_ids uuid[] NOT NULL,\n        assignment_window tstzrange NOT NULL,\n        merge_group_allocation_id uuid,\n        created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n        PRIMARY KEY (booking_id, idempotency_key)\n      )\n    $create_ledger$;\n\n    EXECUTE $ledger_fk_booking$\n      ALTER TABLE public.booking_assignment_idempotency\n        ADD CONSTRAINT booking_assignment_idempotency_booking_id_fkey\n          FOREIGN KEY (booking_id)\n          REFERENCES public.bookings(id)\n          ON DELETE CASCADE\n    $ledger_fk_booking$;\n\n    EXECUTE $ledger_fk_merge$\n      ALTER TABLE public.booking_assignment_idempotency\n        ADD CONSTRAINT booking_assignment_idempotency_merge_group_fkey\n          FOREIGN KEY (merge_group_allocation_id)\n          REFERENCES public.allocations(id)\n          ON DELETE SET NULL\n    $ledger_fk_merge$;\n\n    CREATE INDEX IF NOT EXISTS booking_assignment_idempotency_created_idx\n      ON public.booking_assignment_idempotency (created_at DESC);\n  END IF;\n\n  -- Replace/define RPC v2.\n  EXECUTE $drop_old$\n    DROP FUNCTION IF EXISTS public.assign_tables_atomic_v2(uuid, uuid[], text, boolean, uuid)\n  $drop_old$;\n\n  EXECUTE $create_rpc$\n    CREATE FUNCTION public.assign_tables_atomic_v2(\n      p_booking_id uuid,\n      p_table_ids uuid[],\n      p_idempotency_key text DEFAULT NULL,\n      p_require_adjacency boolean DEFAULT false,\n      p_assigned_by uuid DEFAULT NULL\n    ) RETURNS TABLE (\n      table_id uuid,\n      start_at timestamptz,\n      end_at timestamptz,\n      merge_group_id uuid\n    )\n    LANGUAGE plpgsql\n    SECURITY DEFINER\n    SET search_path = public\n    AS $function$\n    DECLARE\n      v_booking RECORD;\n      v_zone_id uuid;\n      v_restaurant_id uuid;\n      v_service_date date;\n      v_lock_zone int4;\n      v_lock_date int4;\n      v_now timestamptz := timezone('utc', now());\n      v_table_ids uuid[];\n      v_table_count integer;\n      v_table RECORD;\n      v_loaded_count integer := 0;\n      v_slot_id uuid := NULL;\n      v_start_at timestamptz;\n      v_end_at timestamptz;\n      v_window tstzrange;\n      v_timezone text := NULL;\n      v_hold_conflict uuid;\n      v_merge_allocation_id uuid := NULL;\n      v_table_assignment_id uuid;\n      v_existing RECORD;\n      v_adjacency_count integer;\n      v_table_id uuid;\n    BEGIN\n      IF p_table_ids IS NULL OR array_length(p_table_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic_v2 requires at least one table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      SELECT array_agg(DISTINCT table_id ORDER BY table_id)\n      INTO v_table_ids\n      FROM unnest(p_table_ids) AS t(table_id);\n\n      IF v_table_ids IS NULL OR array_length(v_table_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'assign_tables_atomic_v2 requires at least one valid table id'\n          USING ERRCODE = '23514';\n      END IF;\n\n      v_table_count := array_length(v_table_ids, 1);\n\n      SELECT\n        b.*,\n        r.timezone AS restaurant_timezone\n      INTO v_booking\n      FROM public.bookings b\n      LEFT JOIN public.restaurants r ON r.id = b.restaurant_id\n      WHERE b.id = p_booking_id\n      FOR UPDATE;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Booking % not found', p_booking_id\n          USING ERRCODE = 'P0002';\n      END IF;\n\n      v_restaurant_id := v_booking.restaurant_id;\n      v_timezone := COALESCE(NULLIF(v_booking.restaurant_timezone, ''), 'UTC');\n\n      IF v_booking.start_at IS NOT NULL AND v_booking.end_at IS NOT NULL THEN\n        v_start_at := v_booking.start_at;\n        v_end_at := v_booking.end_at;\n      ELSIF v_booking.booking_date IS NOT NULL AND v_booking.start_time IS NOT NULL AND v_booking.end_time IS NOT NULL THEN\n        v_start_at := make_timestamptz(\n          EXTRACT(YEAR FROM v_booking.booking_date)::int,\n          EXTRACT(MONTH FROM v_booking.booking_date)::int,\n          EXTRACT(DAY FROM v_booking.booking_date)::int,\n          EXTRACT(HOUR FROM v_booking.start_time)::int,\n          EXTRACT(MINUTE FROM v_booking.start_time)::int,\n          EXTRACT(SECOND FROM v_booking.start_time),\n          v_timezone\n        );\n        v_end_at := make_timestamptz(\n          EXTRACT(YEAR FROM v_booking.booking_date)::int,\n          EXTRACT(MONTH FROM v_booking.booking_date)::int,\n          EXTRACT(DAY FROM v_booking.booking_date)::int,\n          EXTRACT(HOUR FROM v_booking.end_time)::int,\n          EXTRACT(MINUTE FROM v_booking.end_time)::int,\n          EXTRACT(SECOND FROM v_booking.end_time),\n          v_timezone\n        );\n      ELSE\n        RAISE EXCEPTION 'Booking % missing start/end window', p_booking_id\n          USING ERRCODE = '22000';\n      END IF;\n\n      IF v_start_at >= v_end_at THEN\n        RAISE EXCEPTION 'Booking % has invalid time window', p_booking_id\n          USING ERRCODE = '22000';\n      END IF;\n\n      v_window := tstzrange(v_start_at, v_end_at, '[)');\n\n      FOR v_table IN\n        SELECT id, restaurant_id, zone_id, active, status, mobility\n        FROM public.table_inventory\n        WHERE id = ANY (v_table_ids)\n        ORDER BY id\n        FOR UPDATE\n      LOOP\n        IF v_table.restaurant_id <> v_restaurant_id THEN\n          RAISE EXCEPTION 'Table % belongs to a different restaurant', v_table.id\n            USING ERRCODE = '23503';\n        END IF;\n\n        IF v_table.zone_id IS NULL THEN\n          RAISE EXCEPTION 'Table % is not assigned to a zone', v_table.id\n            USING ERRCODE = '23514';\n        END IF;\n\n        IF v_table.active IS NOT TRUE THEN\n          RAISE EXCEPTION 'Table % is inactive', v_table.id\n            USING ERRCODE = '23514';\n        END IF;\n\n        IF v_zone_id IS NULL THEN\n          v_zone_id := v_table.zone_id;\n        ELSIF v_zone_id <> v_table.zone_id THEN\n          RAISE EXCEPTION 'All tables must belong to the same zone (found %, expected %)', v_table.zone_id, v_zone_id\n            USING ERRCODE = '23514';\n        END IF;\n\n        IF v_table_count > 1 AND v_table.mobility <> 'movable'::public.table_mobility THEN\n          RAISE EXCEPTION 'Merged assignments require movable tables (% is %)', v_table.id, v_table.mobility\n            USING ERRCODE = '23514';\n        END IF;\n\n        v_loaded_count := v_loaded_count + 1;\n      END LOOP;\n\n      IF v_loaded_count <> v_table_count THEN\n        RAISE EXCEPTION 'Unable to load all requested tables for booking %', p_booking_id\n          USING ERRCODE = 'P0002';\n      END IF;\n\n      IF p_require_adjacency AND v_table_count > 1 THEN\n        FOR v_table IN\n          SELECT id FROM unnest(v_table_ids) AS t(id)\n        LOOP\n          SELECT COUNT(*)\n          INTO v_adjacency_count\n          FROM public.table_adjacencies\n          WHERE table_a = v_table.id\n            AND table_b = ANY (v_table_ids)\n            AND table_b <> v_table.id;\n\n          IF COALESCE(v_adjacency_count, 0) = 0 THEN\n            RAISE EXCEPTION 'Table % is not adjacent to the selected set', v_table.id\n              USING ERRCODE = '23514';\n          END IF;\n        END LOOP;\n      END IF;\n\n      v_service_date := v_booking.booking_date;\n      IF v_service_date IS NULL THEN\n        v_service_date := (v_start_at AT TIME ZONE v_timezone)::date;\n      END IF;\n\n      v_lock_zone := hashtext(COALESCE(v_zone_id::text, ''));\n      v_lock_date := COALESCE((v_service_date - DATE '2000-01-01')::int, 0);\n      PERFORM pg_advisory_xact_lock(v_lock_zone, v_lock_date);\n\n      IF p_idempotency_key IS NOT NULL THEN\n        SELECT *\n        INTO v_existing\n        FROM public.booking_assignment_idempotency\n        WHERE booking_id = p_booking_id\n          AND idempotency_key = p_idempotency_key;\n\n        IF FOUND THEN\n          IF v_existing.table_ids IS NULL OR array_length(v_existing.table_ids, 1) <> v_table_count\n             OR (SELECT array_agg(elem ORDER BY elem) FROM unnest(v_existing.table_ids) AS e(elem))\n                <> (SELECT array_agg(elem ORDER BY elem) FROM unnest(v_table_ids) AS e(elem)) THEN\n            RAISE EXCEPTION 'assign_tables_atomic_v2 idempotency mismatch for booking %', p_booking_id\n              USING ERRCODE = 'P0003',\n                    DETAIL = 'Idempotency key reuse detected with a different table set';\n          END IF;\n\n          RETURN QUERY\n            SELECT\n              bta.table_id,\n              lower(v_existing.assignment_window) AS start_at,\n              upper(v_existing.assignment_window) AS end_at,\n              v_existing.merge_group_allocation_id\n            FROM public.booking_table_assignments bta\n            WHERE bta.booking_id = p_booking_id\n              AND bta.idempotency_key = p_idempotency_key\n              AND bta.table_id = ANY (v_table_ids)\n            ORDER BY bta.table_id;\n\n          RETURN;\n        END IF;\n      END IF;\n\n      SELECT th.id\n      INTO v_hold_conflict\n      FROM public.table_holds th\n      JOIN public.table_hold_members thm ON thm.hold_id = th.id\n      WHERE thm.table_id = ANY (v_table_ids)\n        AND th.expires_at > v_now\n        AND (th.booking_id IS NULL OR th.booking_id <> p_booking_id)\n        AND tstzrange(th.start_at, th.end_at, '[)') && v_window\n      LIMIT 1;\n\n      IF FOUND THEN\n        RAISE EXCEPTION 'Hold conflict prevents assignment for booking %', p_booking_id\n          USING ERRCODE = 'P0001',\n                DETAIL = format('Hold % overlaps requested window', v_hold_conflict),\n                HINT = 'Retry after hold expiration or confirm existing hold.';\n      END IF;\n\n      IF v_booking.booking_date IS NOT NULL AND v_booking.start_time IS NOT NULL THEN\n        SELECT id\n        INTO v_slot_id\n        FROM public.booking_slots\n        WHERE restaurant_id = v_restaurant_id\n          AND slot_date = v_booking.booking_date\n          AND slot_time = v_booking.start_time\n        LIMIT 1;\n\n        IF v_slot_id IS NULL THEN\n          SELECT public.get_or_create_booking_slot(v_restaurant_id, v_booking.booking_date, v_booking.start_time, 999)\n          INTO v_slot_id;\n        END IF;\n      END IF;\n\n      IF v_table_count > 1 THEN\n        v_merge_allocation_id := gen_random_uuid();\n\n        BEGIN\n          INSERT INTO public.allocations (\n            id,\n            booking_id,\n            restaurant_id,\n            resource_type,\n            resource_id,\n            \\"window\\",\n            created_by,\n            shadow,\n            created_at,\n            updated_at\n          ) VALUES (\n            v_merge_allocation_id,\n            p_booking_id,\n            v_restaurant_id,\n            'merge_group',\n            v_merge_allocation_id,\n            v_window,\n            p_assigned_by,\n            false,\n            v_now,\n            v_now\n          )\n          ON CONFLICT ON CONSTRAINT allocations_booking_resource_key DO UPDATE\n          SET \\"window\\" = EXCLUDED.\\"window\\",\n              created_by = COALESCE(EXCLUDED.created_by, public.allocations.created_by),\n              updated_at = v_now;\n        EXCEPTION\n          WHEN unique_violation OR exclusion_violation THEN\n            RAISE EXCEPTION 'allocations_no_overlap'\n              USING ERRCODE = 'P0001',\n                    DETAIL = format('Merge group overlaps requested window for booking %s', p_booking_id);\n        END;\n      END IF;\n\n      FOREACH v_table_id IN ARRAY v_table_ids LOOP\n        BEGIN\n          INSERT INTO public.booking_table_assignments (\n            booking_id,\n            table_id,\n            slot_id,\n            assigned_by,\n            idempotency_key,\n            merge_group_id\n          ) VALUES (\n            p_booking_id,\n            v_table_id,\n            v_slot_id,\n            p_assigned_by,\n            p_idempotency_key,\n            v_merge_allocation_id\n          )\n          ON CONFLICT (booking_id, table_id) DO UPDATE\n          SET assigned_at = v_now,\n              assigned_by = COALESCE(EXCLUDED.assigned_by, public.booking_table_assignments.assigned_by),\n              idempotency_key = COALESCE(EXCLUDED.idempotency_key, public.booking_table_assignments.idempotency_key),\n              merge_group_id = COALESCE(EXCLUDED.merge_group_id, public.booking_table_assignments.merge_group_id),\n              slot_id = COALESCE(EXCLUDED.slot_id, public.booking_table_assignments.slot_id)\n          RETURNING id INTO v_table_assignment_id;\n        EXCEPTION\n          WHEN unique_violation THEN\n            RAISE EXCEPTION 'assign_tables_atomic_v2 assignment duplicate for table %', v_table_id\n              USING ERRCODE = 'P0001';\n        END;\n\n        BEGIN\n          INSERT INTO public.allocations (\n            booking_id,\n            restaurant_id,\n            resource_type,\n            resource_id,\n            \\"window\\",\n            created_by,\n            shadow,\n            created_at,\n            updated_at\n          ) VALUES (\n            p_booking_id,\n            v_restaurant_id,\n            'table',\n            v_table_id,\n            v_window,\n            p_assigned_by,\n            false,\n            v_now,\n            v_now\n          )\n          ON CONFLICT ON CONSTRAINT allocations_booking_resource_key DO UPDATE\n          SET \\"window\\" = EXCLUDED.\\"window\\",\n              created_by = COALESCE(EXCLUDED.created_by, public.allocations.created_by),\n              updated_at = v_now;\n        EXCEPTION\n          WHEN unique_violation OR exclusion_violation THEN\n            RAISE EXCEPTION 'allocations_no_overlap'\n              USING ERRCODE = 'P0001',\n                    DETAIL = format('Resource %s overlaps requested window for booking %s', v_table_id, p_booking_id);\n        END;\n\n        UPDATE public.table_inventory\n        SET status = 'reserved'::public.table_status\n        WHERE id = v_table_id;\n\n        table_id := v_table_id;\n        start_at := v_start_at;\n        end_at := v_end_at;\n        merge_group_id := v_merge_allocation_id;\n        RETURN NEXT;\n      END LOOP;\n\n      IF p_idempotency_key IS NOT NULL THEN\n        INSERT INTO public.booking_assignment_idempotency (\n          booking_id,\n          idempotency_key,\n          table_ids,\n          assignment_window,\n          merge_group_allocation_id,\n          created_at\n        ) VALUES (\n          p_booking_id,\n          p_idempotency_key,\n          v_table_ids,\n          v_window,\n          v_merge_allocation_id,\n          v_now\n        )\n        ON CONFLICT (booking_id, idempotency_key) DO NOTHING;\n      END IF;\n    END;\n    $function$\n  $create_rpc$;\n\n  EXECUTE $alter_rpc$\n    ALTER FUNCTION public.assign_tables_atomic_v2(uuid, uuid[], text, boolean, uuid) OWNER TO postgres\n  $alter_rpc$;\n\n  EXECUTE $grant_rpc$\n    GRANT ALL ON FUNCTION public.assign_tables_atomic_v2(uuid, uuid[], text, boolean, uuid) TO service_role\n  $grant_rpc$;\nEND;\n$migration$"}	assign_tables_atomic_v2
20251026105100	{"-- Remove legacy assign_table_to_booking RPC\n-- This migration drops the old function signature if it exists\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_proc\n    WHERE proname = 'assign_table_to_booking'\n      AND pg_function_is_visible(oid)\n      AND pg_get_function_identity_arguments(oid) = 'p_booking_id uuid, p_table_id uuid, p_assigned_by uuid, p_notes text'\n  ) THEN\n    DROP FUNCTION public.assign_table_to_booking(uuid, uuid, uuid, text);\n  END IF;\nEND;\n$$"}	cleanup_legacy_assign_rpc
20251026161309	{"-- Create table_holds and table_hold_members unconditionally\n-- This migration ensures these tables exist on the remote database\n\nCREATE TABLE IF NOT EXISTS public.table_holds (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,\n  booking_id uuid REFERENCES public.bookings(id) ON DELETE SET NULL,\n  zone_id uuid NOT NULL REFERENCES public.zones(id) ON DELETE CASCADE,\n  start_at timestamptz NOT NULL,\n  end_at timestamptz NOT NULL,\n  expires_at timestamptz NOT NULL,\n  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n  updated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n  metadata jsonb,\n  CONSTRAINT table_holds_window_check CHECK (start_at < end_at)\n)","COMMENT ON TABLE public.table_holds IS\n  'Ephemeral table reservations to guard allocations during quoting/confirmation flows.'","CREATE INDEX IF NOT EXISTS table_holds_expires_at_idx\n  ON public.table_holds (expires_at)","CREATE INDEX IF NOT EXISTS table_holds_zone_start_idx\n  ON public.table_holds (zone_id, start_at)","CREATE INDEX IF NOT EXISTS table_holds_booking_idx\n  ON public.table_holds (booking_id)","-- Create table_hold_members\nCREATE TABLE IF NOT EXISTS public.table_hold_members (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hold_id uuid NOT NULL REFERENCES public.table_holds(id) ON DELETE CASCADE,\n  table_id uuid NOT NULL REFERENCES public.table_inventory(id) ON DELETE RESTRICT,\n  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),\n  UNIQUE (hold_id, table_id)\n)","CREATE INDEX IF NOT EXISTS table_hold_members_table_idx\n  ON public.table_hold_members (table_id)"}	add_table_holds_unconditional
20251026162123	{"-- Ensure allocations.resource_type allows hold mirrors created by manual holds.\n-- +goose Up\nALTER TABLE public.allocations\n  DROP CONSTRAINT IF EXISTS allocations_resource_type_check","ALTER TABLE public.allocations\n  ADD CONSTRAINT allocations_resource_type_check\n    CHECK (resource_type = ANY (ARRAY['table'::text, 'hold'::text, 'merge_group'::text]))","-- +goose Down\nALTER TABLE public.allocations\n  DROP CONSTRAINT IF EXISTS allocations_resource_type_check","ALTER TABLE public.allocations\n  ADD CONSTRAINT allocations_resource_type_check\n    CHECK (resource_type = ANY (ARRAY['table'::text, 'merge_group'::text]))"}	allow_hold_allocations
20251026163200	{"-- Ensure staff APIs can read table holds through the authenticated role.\n-- +goose Up\nGRANT SELECT ON TABLE public.table_holds TO authenticated","GRANT SELECT ON TABLE public.table_hold_members TO authenticated","-- +goose Down\nREVOKE SELECT ON TABLE public.table_hold_members FROM authenticated","REVOKE SELECT ON TABLE public.table_holds FROM authenticated"}	grant_table_hold_access
20251026164913	{"-- Enable RLS and scoped policies for table holds and members\n-- +goose Up\nALTER TABLE public.table_holds ENABLE ROW LEVEL SECURITY","ALTER TABLE public.table_hold_members ENABLE ROW LEVEL SECURITY","GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_holds TO service_role","GRANT SELECT ON TABLE public.table_holds TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_hold_members TO service_role","GRANT SELECT ON TABLE public.table_hold_members TO authenticated","CREATE POLICY \\"Service role can manage table holds\\" ON public.table_holds\n  TO service_role\n  USING (true)\n  WITH CHECK (true)","CREATE POLICY \\"Staff can view table holds\\" ON public.table_holds\n  FOR SELECT\n  TO authenticated\n  USING (\n    restaurant_id IN (\n      SELECT public.user_restaurants() AS user_restaurants\n    )\n  )","CREATE POLICY \\"Service role can manage table hold members\\" ON public.table_hold_members\n  TO service_role\n  USING (true)\n  WITH CHECK (true)","CREATE POLICY \\"Staff can view table hold members\\" ON public.table_hold_members\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM public.table_holds h\n      WHERE h.id = table_hold_members.hold_id\n        AND h.restaurant_id IN (\n          SELECT public.user_restaurants() AS user_restaurants\n        )\n    )\n  )","-- +goose Down\nDROP POLICY IF EXISTS \\"Staff can view table hold members\\" ON public.table_hold_members","DROP POLICY IF EXISTS \\"Service role can manage table hold members\\" ON public.table_hold_members","DROP POLICY IF EXISTS \\"Staff can view table holds\\" ON public.table_holds","DROP POLICY IF EXISTS \\"Service role can manage table holds\\" ON public.table_holds","REVOKE SELECT ON TABLE public.table_hold_members FROM authenticated","REVOKE SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_hold_members FROM service_role","REVOKE SELECT ON TABLE public.table_holds FROM authenticated","REVOKE SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_holds FROM service_role","ALTER TABLE public.table_hold_members DISABLE ROW LEVEL SECURITY","ALTER TABLE public.table_holds DISABLE ROW LEVEL SECURITY"}	add_table_holds_rls
20251026171000	{"-- Ensure table_holds and table_hold_members grant coverage is in place after earlier schema drift.\n-- +goose Up\nALTER TABLE public.table_holds ENABLE ROW LEVEL SECURITY","ALTER TABLE public.table_hold_members ENABLE ROW LEVEL SECURITY","GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_holds TO service_role","GRANT SELECT ON TABLE public.table_holds TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.table_hold_members TO service_role","GRANT SELECT ON TABLE public.table_hold_members TO authenticated","DROP POLICY IF EXISTS \\"Service role can manage table holds\\" ON public.table_holds","CREATE POLICY \\"Service role can manage table holds\\" ON public.table_holds\n  TO service_role\n  USING (true)\n  WITH CHECK (true)","DROP POLICY IF EXISTS \\"Staff can view table holds\\" ON public.table_holds","CREATE POLICY \\"Staff can view table holds\\" ON public.table_holds\n  FOR SELECT\n  TO authenticated\n  USING (\n    restaurant_id IN (\n      SELECT public.user_restaurants() AS user_restaurants\n    )\n  )","DROP POLICY IF EXISTS \\"Service role can manage table hold members\\" ON public.table_hold_members","CREATE POLICY \\"Service role can manage table hold members\\" ON public.table_hold_members\n  TO service_role\n  USING (true)\n  WITH CHECK (true)","DROP POLICY IF EXISTS \\"Staff can view table hold members\\" ON public.table_hold_members","CREATE POLICY \\"Staff can view table hold members\\" ON public.table_hold_members\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM public.table_holds h\n      WHERE h.id = table_hold_members.hold_id\n        AND h.restaurant_id IN (\n          SELECT public.user_restaurants() AS user_restaurants\n        )\n    )\n  )","-- +goose Down\nDROP POLICY IF EXISTS \\"Staff can view table hold members\\" ON public.table_hold_members","DROP POLICY IF EXISTS \\"Service role can manage table hold members\\" ON public.table_hold_members","DROP POLICY